"""Explicit advanced CLI operations; core command startup stays standard-library only."""
import json
from pathlib import Path

from ontology_core import (atomic_write, canonical_bytes, exact, read_bytes,
                           read_json, require, safe_path, sha256)

READ_COMMANDS = {"advanced-health", "dataset", "sparql", "shacl", "infer", "semantic-search",
                 "proposal-list", "proposal-show", "generation-show"}
COMMANDS = READ_COMMANDS | {"profile-setup", "profile-configure", "prepare-model", "build-semantic-index",
                           "export-rdf", "import-rdf", "proposal-save", "proposal-validate", "proposal-decide", "proposal-publish",
                           "generation-prepare", "generation-capture", "guard-preview", "guard-apply", "guard-recover", "workbench"}


def register(commands):
    from ontology_health import arguments
    arguments(commands.add_parser("advanced-health"), advanced=True)
    setup = commands.add_parser("profile-setup")
    setup.add_argument("profile", choices=("standards", "semantic"))
    setup.add_argument("--provision", action="store_true", help="Explicitly install the selected hashed package lock.")
    config = commands.add_parser("profile-configure")
    config.add_argument("payload", help="Exact profile change, current config hash and current setup authority.")
    commands.add_parser("prepare-model")
    index = commands.add_parser("build-semantic-index")
    index.add_argument("--document", action="append", default=[])
    sem = commands.add_parser("semantic-search")
    sem.add_argument("query"); sem.add_argument("--limit", type=int); sem.add_argument("--max-bytes", type=int)
    for name in ("dataset", "sparql", "shacl"):
        parser = commands.add_parser(name)
        parser.add_argument("--graph", action="append")
        parser.add_argument("--limits-file")
        if name == "sparql":
            query = parser.add_mutually_exclusive_group(required=True)
            query.add_argument("--query"); query.add_argument("--query-file")
        if name == "shacl":
            parser.add_argument("--shapes", action="append", default=[])
    infer = commands.add_parser("infer")
    infer.add_argument("--goal", nargs=3, action="append", default=[])
    infer.add_argument("--premise-id", action="append")
    infer.add_argument("--expected-snapshot"); infer.add_argument("--limits-file")
    export = commands.add_parser("export-rdf")
    export.add_argument("--serialization", choices=("json-ld", "turtle", "xml"), required=True)
    export.add_argument("--graph"); export.add_argument("--output", required=True)
    export.add_argument("--expected-output-sha256")
    imp = commands.add_parser("import-rdf")
    imp.add_argument("input"); imp.add_argument("--serialization", choices=("json-ld", "turtle", "xml"), required=True)
    imp.add_argument("--manifest"); imp.add_argument("--reason", required=True)
    for name in ("proposal-save", "generation-prepare", "generation-capture", "guard-preview", "guard-apply", "guard-recover"):
        commands.add_parser(name).add_argument("payload")
    commands.add_parser("proposal-list")
    show = commands.add_parser("proposal-show"); show.add_argument("proposal_id"); show.add_argument("--revision", type=int)
    gen = commands.add_parser("generation-show"); gen.add_argument("request_id")
    val = commands.add_parser("proposal-validate"); val.add_argument("proposal_id"); val.add_argument("--revision", type=int, required=True)
    decision = commands.add_parser("proposal-decide")
    decision.add_argument("proposal_id"); decision.add_argument("decision", choices=("accept", "reject", "reopen", "supersede", "discard"))
    decision.add_argument("--revision", type=int, required=True); decision.add_argument("--reason", required=True)
    decision.add_argument("--validation-sha256"); decision.add_argument("--superseded-by")
    publish = commands.add_parser("proposal-publish")
    publish.add_argument("proposal_id"); publish.add_argument("--revision", type=int, required=True)
    publish.add_argument("--grant-file", required=True); publish.add_argument("--expected-review-sha256", required=True)
    workbench = commands.add_parser("workbench")
    workbench.add_argument("--authority-file"); workbench.add_argument("--port", type=int, default=0)
    workbench.add_argument("--session-file", required=True, help="Private runtime file for the short-lived local bootstrap URL.")


def _json(root, path):
    return read_json(safe_path(root, path))


def dispatch(root, args):
    name = args.command
    if name == "advanced-health":
        from ontology_health import advanced_health
        return advanced_health(root, scope=args.scope, level=args.level, required=args.require, workbench_url=args.workbench_url)
    if name == "profile-setup":
        if args.profile == "semantic":
            from ontology_semantic import setup_profile, health
            return setup_profile(root) if args.provision else health(root)
        from ontology_profiles import setup_profile
        return setup_profile(root, "standards", provision=args.provision)
    if name == "profile-configure":
        from ontology_profiles import configure_profile
        value = _json(root, args.payload)
        exact(value, ("profile", "enabled", "expected_config_sha256", "authority"))
        return configure_profile(root, **value)
    if name == "prepare-model":
        from ontology_semantic import prepare_model
        return prepare_model(root)
    if name == "build-semantic-index":
        from ontology_semantic import build_index
        return build_index(root, documents=args.document)
    if name == "semantic-search":
        from ontology_semantic import search
        return search(root, args.query, limit=args.limit, max_bytes=args.max_bytes)
    if name in {"dataset", "sparql", "shacl", "infer", "export-rdf", "import-rdf"}:
        import ontology_standards as standards
        limits = _json(root, args.limits_file) if getattr(args, "limits_file", None) else None
        if name == "dataset": return standards.dataset(root, graphs=args.graph, limits=limits)
        if name == "sparql":
            query = args.query if args.query is not None else read_bytes(safe_path(root, args.query_file)).decode("utf-8")
            return standards.query(root, query, graphs=args.graph, limits=limits)
        if name == "shacl":
            shapes = [read_bytes(safe_path(root, path)).decode("utf-8") for path in args.shapes]
            return standards.validate(root, graphs=args.graph, shapes=shapes, limits=limits)
        if name == "infer":
            return standards.infer(root, goals=args.goal, premise_ids=args.premise_id, expected_snapshot=args.expected_snapshot, limits=limits)
        if name == "import-rdf":
            from ontology_proposals import stage_rdf_import
            data = read_bytes(safe_path(root, args.input))
            staged = standards.stage_import(root, data.decode("utf-8"), args.serialization,
                                            manifest=_json(root, args.manifest) if args.manifest else None)
            if not staged.get("complete"): return staged
            return stage_rdf_import(root, staged, {"path": args.input, "sha256": sha256(data), "locator": "line:1"}, args.reason)
        result = standards.export(root, args.serialization, selected_graph=args.graph)
        if not result.get("complete"): return result
        require(args.output.startswith((".sys4ai/ontology/exports/", "exports/")), "export_scope", "Use an explicitly selected export directory, never canonical ontology paths.")
        target = safe_path(root, args.output, must_exist=False)
        require((sha256(target) if target.exists() else None) == args.expected_output_sha256,
                "export_conflict", "Export overwrite requires the exact current destination hash.")
        manifest_path = args.output + ".manifest.json"
        require(not safe_path(root, manifest_path, must_exist=False).exists(), "export_conflict", "Select a new export with a new companion manifest.")
        result["manifest"].update(context=result["context"])
        atomic_write(root, manifest_path, canonical_bytes(result["manifest"]), None)
        try:
            atomic_write(root, args.output, result["content"].encode("utf-8"), args.expected_output_sha256)
        except Exception:
            return {"status": "partial", "mutated": True, "manifest": manifest_path,
                    "diagnostic": "The manifest was written but the selected export was not confirmed. Inspect both paths; do not replay blindly."}
        return {"status": "exported", "output": args.output, "sha256": sha256(target), "manifest": manifest_path,
                "manifest_sha256": sha256(safe_path(root, manifest_path)), "mutated": True}
    if name.startswith("proposal-"):
        import ontology_proposals as proposals
        if name == "proposal-list": return {"status": "ok", "proposals": proposals.list_proposals(root), "mutated": False}
        if name == "proposal-show": return proposals.open_proposal(root, args.proposal_id, revision=args.revision)
        if name == "proposal-save":
            data = _json(root, args.payload)
            exact(data, ("candidate", "rationale"), ("proposal_id", "expected_revision", "evidence", "uncertainty", "generator", "source_packet", "addressed_findings"))
            return proposals.save(root, **data)
        if name == "proposal-validate":
            from ontology_proposal_validation import validate_candidate
            return validate_candidate(root, args.proposal_id, expected_revision=args.revision)
        if name == "proposal-publish":
            from ontology_proposal_validation import publish_revision
            return publish_revision(root, args.proposal_id, _json(root, args.grant_file), expected_revision=args.revision,
                                    expected_review_sha256=args.expected_review_sha256)
        return proposals.decide(root, args.proposal_id, expected_revision=args.revision, decision=args.decision,
                                reason=args.reason, validation_sha256=args.validation_sha256, superseded_by=args.superseded_by)
    if name.startswith("generation-"):
        import ontology_generation as generation
        if name == "generation-show": return generation.read_request(root, args.request_id)
        data = _json(root, args.payload)
        if name == "generation-prepare":
            exact(data, ("sources", "context_ids", "instruction", "runtime"),
                  ("request_id", "previous_request", "findings", "proposal_id"))
            return generation.prepare(root, **data)
        exact(data, ("request_id", "result", "native_receipt"))
        return generation.capture(root, **data)
    if name.startswith("guard-"):
        import ontology_guard_setup as guards
        data = _json(root, args.payload)
        if name == "guard-preview":
            exact(data, ("operation_id", "contract", "repair", "verification"))
            return guards.preview_enablement(root, **data)
        if name == "guard-apply":
            exact(data, ("preview", "grant")); return guards.apply(root, **data)
        exact(data, ("operation_id", "grant")); return guards.recover(root, **data)
    if name == "workbench":
        import os
        from ontology_workbench import Workbench, trusted_authority
        authority = trusted_authority(root, **_json(root, args.authority_file)) if args.authority_file else None
        service = Workbench(root, authority, port=args.port)
        require(args.session_file.startswith(".sys4ai/ontology/workbench/"), "session_scope", "Session credentials belong only in the private workbench runtime directory.")
        target = safe_path(root, args.session_file, must_exist=False)
        require(not target.exists(), "session_conflict", "Select a new private session file.")
        target.parent.mkdir(parents=True, exist_ok=True)
        # Tokens are written only to this private runtime file, never CLI logs.
        with os.fdopen(os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600), "w") as stream:
            json.dump({"url": service.bootstrap_url(), "origin": service.origin}, stream)
        session_digest = sha256(target)
        try:
            service.start()
            print(json.dumps({"status": "running", "origin": service.origin, "session_file": args.session_file,
                              "current_readiness": service.startup_readiness}), flush=True)
            while service.thread.is_alive():
                service.thread.join(timeout=1)
        except KeyboardInterrupt:
            pass
        finally:
            service.close()
            # Only this call's exclusively created private runtime credential.
            if target.exists() and not target.is_symlink() and sha256(target) == session_digest:
                target.unlink()
        return {"status": "stopped", "origin": service.origin}
    require(False, "unsupported_operation", "Unknown advanced operation.")

"""Exact, optional semantic checks at the owning helpers' mutation boundaries.

This module grants no authority.  The public helper runs its existing authorizer
after this check.  Context variables only carry a decision down that helper's
current call stack; no reusable pass or authorization is cached.
"""
from __future__ import annotations

import argparse
import ast
from contextvars import ContextVar
from dataclasses import fields, is_dataclass
import hashlib
import importlib.util
import inspect
import json
import math
from pathlib import Path
import re
import sys
import time

ACTIVE = ContextVar("sys4ai_ontology_guard_actions", default=())
BASE = "urn:sys4ai:ontology:action:"
FAMILIES = {"ontology", "memory", "task", "trd", "plan", "role", "template", "setup"}
MAX_FILES = 10000
MAX_BYTES = 64 * 1024 * 1024
ENGINE_SOURCE_SHA256 = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
CAPABILITIES = {
    "ontology": "OntologyPublication", "memory": "MemoryMaintenance",
    "task": "TaskLifecycleManagement", "trd": "RequirementsManagement",
    "plan": "ImplementationPlanManagement", "role": "RoleCatalogManagement",
    "template": "TemplateDistribution", "setup": "ProjectCapabilitySetup",
}
PROVIDERS = {
    ".agents/skills/ontology/scripts/ontology_publication.py": "ontology",
    ".agents/skills/ontology/scripts/ontology_profiles.py": "setup",
    ".agents/skills/memory/scripts/memory_recovery.py": "memory",
    ".agents/skills/memory/scripts/memory_publish.py": "memory",
    ".agents/skills/memory/scripts/memory_capture.py": "memory",
    ".agents/skills/memory/scripts/memory_maintenance.py": "memory",
    ".agents/skills/agent-task/scripts/task_state.py": "task",
    ".agents/skills/to-trd/scripts/trd.py": "trd",
    ".agents/skills/to-implementation-plan/scripts/plan_state.py": "plan",
    ".agents/skills/manage-subagent-roles/scripts/role_catalog.py": "role",
    "tools/template_update.py": "template",
    ".agents/skills/init-new-project/scripts/init_new_project.py": "setup",
}
RULES = {"typed-input", "owned-targets", "installed-capability", "current-governance", "owner-semantics"}
LIFECYCLES = {("task", "response_transaction"): "task", ("trd", "set_status"): "trd", ("plan", "handle_set_status"): "plan"}


def validate_contract(contract):
    """Reject unknown executable meaning, rather than silently ignoring a rule."""
    fail(isinstance(contract, dict) and set(contract) == {"schema_version", "id", "semantic_profile", "shapes", "actions", "optional_actions", "lifecycles", "uncovered"}
         and contract.get("schema_version") == 1 and contract.get("semantic_profile") == "sys4ai-actions-v1",
         "guard_unsupported", "Select the supported complete typed action contract (sys4ai-actions-v1).")
    fail(set(contract["lifecycles"]) == {"task", "trd", "plan"}, "guard_unsupported", "Unsupported or missing lifecycle vocabulary.")
    for name, lifecycle in contract["lifecycles"].items():
        fail(isinstance(lifecycle, dict) and set(lifecycle) == {"identity_pattern", "transitions"}
             and isinstance(lifecycle["identity_pattern"], str) and isinstance(lifecycle["transitions"], dict)
             and lifecycle["transitions"], "guard_schema", "Malformed semantic lifecycle contract.", lifecycle=name)
        for state, after in lifecycle["transitions"].items():
            fail(isinstance(state, str) and isinstance(after, list) and len(after) == len(set(after))
                 and all(value in lifecycle["transitions"] for value in after), "guard_schema", "Lifecycle edges must resolve to declared states.", lifecycle=name)
    fail(isinstance(contract["actions"], list) and isinstance(contract["optional_actions"], list), "guard_schema", "Action definitions must be arrays.")
    for action in contract["actions"] + contract["optional_actions"]:
        fields = {"id", "family", "operation", "input_type", "target_type", "capability", "governing_sources", "dispatch", "semantic_rules", "lifecycle"}
        if action in contract["optional_actions"]:
            fields.add("applicability")
        fail(isinstance(action, dict) and set(action) == fields,
             "guard_unsupported", "Unknown or incomplete action rule contract.")
        family, operation = action["family"], action["operation"]
        fail(family in FAMILIES and isinstance(operation, str) and re.fullmatch(r"[a-z_]+", operation)
             and action["id"] == BASE + family + ":" + operation, "guard_schema", "Action identity must name its exact family and operation.")
        fail(action["input_type"] == family + "-" + operation + "-request" and action["target_type"] in {value + "-owned-artifact" for value in FAMILIES}
             and action["capability"] in {BASE + "capability:" + value for value in CAPABILITIES.values()}, "guard_unsupported", "Unsupported input, target or concrete capability type.", action_id=action["id"])
        fail(isinstance(action["semantic_rules"], list) and set(action["semantic_rules"]) == RULES and len(action["semantic_rules"]) == len(RULES)
             and action["lifecycle"] == LIFECYCLES.get((family, operation)), "guard_unsupported", "Unsupported, duplicate or missing semantic rules.", action_id=action["id"])
        fail(action["governing_sources"] == ["SOUL.md", "AGENTS.md", "ROLE.md"], "guard_unsupported", "Action governance must name the current destination-local source trio.")
        dispatch = action["dispatch"]
        fail(isinstance(dispatch, dict) and set(dispatch) == {"path", "symbol"} and PROVIDERS.get(dispatch["path"]) == family
             and dispatch["symbol"] == ("Store." + operation if family == "trd" else operation), "guard_unsupported", "Unsupported owning dispatch interface.", action_id=action["id"])
    return contract


class GuardError(ValueError):
    def __init__(self, code, message, details=None):
        super().__init__(message)
        self.code, self.details = code, details or {}

    def __str__(self):
        # Some owning CLIs retain only exception text. Keep their diagnostic
        # useful without serializing arguments, RDF values, or full contexts.
        selected = ["condition=" + self.code] if re.fullmatch(r"[A-Za-z0-9_-]{1,80}", self.code) else []
        action = self.details.get("action_id")
        if isinstance(action, str) and len(action) <= 160 and re.fullmatch(r"urn:sys4ai:ontology:action:[a-z_]+:[a-z_]+", action):
            selected.append("action=" + action)
        binding = self.details.get("contract", self.details.get("configuration"))
        if isinstance(binding, dict) and isinstance(binding.get("path"), str) and isinstance(binding.get("sha256"), str) and re.fullmatch(r"[A-Za-z0-9_./-]{1,200}", binding["path"]) and re.fullmatch(r"[0-9a-f]{64}", binding["sha256"]):
            selected.append("source=" + binding["path"] + "@" + binding["sha256"])
        backend = self.details.get("backend", {})
        if isinstance(backend, dict):
            status = backend.get("status")
            if isinstance(status, str) and re.fullmatch(r"[A-Za-z0-9_-]{1,80}", status):
                selected.append("backend=" + status)
            identifiers = set()
            records = [row for name in ("findings", "diagnostics") for row in (backend[name] if isinstance(backend.get(name), list) else [])]
            for finding in records:
                if not isinstance(finding, dict):
                    continue
                value = finding.get("code") or str(finding.get("constraint", "")).rsplit("#", 1)[-1]
                if isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9_-]{1,80}", value):
                    identifiers.add(value)
            if identifiers:
                selected.append("findings=" + ",".join(sorted(identifiers)[:3]))
        return (super().__str__()[:300] + (" [" + "; ".join(selected) + "]" if selected else ""))[:1200]


def fail(condition, code, message, **details):
    if not condition:
        raise GuardError(code, message, details)


class _GuardBudget:
    """One deadline shared by every backend phase of one semantic decision."""
    def __init__(self, root, *, clock=None):
        from ontology_limits import limits
        self.clock = clock or time.monotonic
        self.started = self.clock()
        self.bounds = limits(_json(Path(root) / "ontology-advanced.yaml").get("limits", {}))
        self.seconds = min(5, self.bounds["guard_seconds"])
        self.deadline = self.started + self.seconds

    def is_set(self):
        # The existing supervised worker polls this while running and kills
        # its process group on expiry. No background thread may dispatch work.
        return self.clock() >= self.deadline

    def check(self, backend=None):
        fail(not self.is_set(), "guard_timeout",
             "The shared semantic evaluation budget expired; no action was dispatched. Resolve the expensive input or retry with a smaller selected graph.",
             limit_seconds=self.seconds, elapsed_seconds=round(self.clock() - self.started, 4),
             **({"backend": backend} if isinstance(backend, dict) else {}))

    def evaluate(self, function, *args, **kwargs):
        self.check()
        remaining = max(1, math.ceil(self.deadline - self.clock()))
        bounds = {key: min(remaining, self.bounds[key]) for key in ("query_seconds", "reasoning_seconds")}
        result = function(*args, **kwargs, limits=bounds, cancel=self)
        self.check(result)
        return result


def encoded(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False).encode()


def digest(value):
    return hashlib.sha256(value if isinstance(value, bytes) else encoded(value)).hexdigest()


def _json(path):
    def pairs(items):
        result = {}
        for key, value in items:
            fail(key not in result, "guard_schema", "Duplicate configuration key.", key=key)
            result[key] = value
        return result
    try:
        return json.loads(path.read_text(), object_pairs_hook=pairs)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise GuardError("guard_unavailable", "Guard configuration cannot be read as strict JSON.", {"path": str(path)}) from exc


def profile(root):
    root = Path(root).absolute()
    path = root / "ontology-advanced.yaml"
    if not path.exists() and not path.is_symlink():
        return None
    fail(not path.is_symlink() and path.is_file(), "guard_unavailable", "Unsafe advanced configuration path.")
    config = _json(path)
    fail(isinstance(config, dict) and config.get("schema_version") == 1 and isinstance(config.get("profiles"), dict),
         "guard_schema", "Unsupported advanced configuration.")
    selected = config["profiles"].get("guards", {"enabled": False})
    fail(isinstance(selected, dict) and type(selected.get("enabled")) is bool,
         "guard_schema", "Guard profile must explicitly select a Boolean enabled value.")
    if not selected["enabled"]:
        fail(set(selected) == {"enabled"}, "guard_schema", "Disabled guard profile has unsupported fields.")
        return None
    fail(set(selected) == {"enabled", "contract", "adapters", "bootstrap"}, "guard_schema", "Enabled guard profile requires the exact contract, adapters and bootstrap bindings.")
    return selected


def checked_path(root, value):
    path = Path(value)
    fail(not path.is_absolute() and path.parts and ".." not in path.parts, "guard_scope", "Guard paths must be project relative.", path=str(value))
    current = Path(root)
    for part in path.parts:
        current /= part
        fail(not current.is_symlink(), "guard_scope", "Guard paths cannot traverse symbolic links.", path=str(value))
    return current


def read_bound(root, binding):
    fail(isinstance(binding, dict) and set(binding) == {"path", "sha256"} and isinstance(binding["path"], str)
         and isinstance(binding["sha256"], str) and re.fullmatch(r"[0-9a-f]{64}", binding["sha256"]),
         "guard_schema", "Malformed exact file binding.")
    path = checked_path(root, binding["path"])
    fail(path.is_file(), "guard_unavailable", "Required guard file is absent.", path=binding["path"])
    raw = path.read_bytes()
    fail(digest(raw) == binding["sha256"], "guard_stale", "A bound guard source changed; select an exact reviewed repair.", path=binding["path"])
    return raw


def normalize(value, depth=0):
    fail(depth <= 32, "guard_schema", "Action nesting exceeds its bound.")
    if value is None or type(value) in (bool, int, str):
        if isinstance(value, str):
            fail(len(value.encode()) <= 4 * 1024 * 1024, "guard_schema", "Action text exceeds its bound.")
        return value
    if isinstance(value, float):
        fail(math.isfinite(value), "guard_schema", "Action numbers must be finite.")
        return value
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, bytes):
        return {"bytes_sha256": digest(value), "byte_count": len(value)}
    if isinstance(value, argparse.Namespace):
        value = vars(value)
    elif is_dataclass(value):
        value = {field.name: getattr(value, field.name) for field in fields(value)}
    if isinstance(value, dict):
        fail(len(value) <= 20000 and all(isinstance(key, str) for key in value), "guard_schema", "Action objects require bounded string keys.")
        return {key: normalize(item, depth + 1) for key, item in value.items()}
    if isinstance(value, (list, tuple, set, frozenset)):
        fail(len(value) <= 20000, "guard_schema", "Action collection exceeds its bound.")
        items = [normalize(item, depth + 1) for item in value]
        return sorted(items, key=lambda item: encoded(item)) if isinstance(value, (set, frozenset)) else items
    if callable(value):
        code = getattr(value, "__code__", None)
        result = {"callable": getattr(value, "__qualname__", type(value).__name__),
                  "code_sha256": digest(code.co_code) if code else None}
        if getattr(value, "__name__", None) == "mutate" and code:
            result["captured_request"] = {name: normalize(cell.cell_contents, depth + 1)
                for name, cell in zip(code.co_freevars, value.__closure__ or ())}
        return result
    # Store instances only supply their project root, never private object state.
    for key in ("project_root", "root"):
        if isinstance(getattr(value, key, None), Path):
            return {key: str(getattr(value, key)), **{name: str(getattr(value, name)) for name in ("folder", "lock_path") if isinstance(getattr(value, name, None), Path)}}
    raise GuardError("guard_schema", "Unsupported action argument type.", {"type": type(value).__name__})


def _snapshot(root, paths):
    result, count = {}, 0
    for relative in sorted(set(paths)):
        path = checked_path(root, relative)
        if not path.exists():
            result[relative] = None
            continue
        if path.is_dir():
            result[relative] = None  # A helper may create its empty lock parent.
        found = sorted(path.rglob("*")) if path.is_dir() else [path]
        for item in found:
            rel = item.relative_to(root).as_posix()
            # Lock bookkeeping and projection temporaries are owned by the helper.
            if any(part.startswith(".") for part in Path(rel).parts if part != ".sys4ai"):
                continue
            fail(not item.is_symlink(), "guard_scope", "Target inventory contains a symbolic link.", path=rel)
            if not item.is_file():
                continue
            raw = item.read_bytes()
            count += len(raw)
            fail(len(result) < MAX_FILES and count <= MAX_BYTES, "guard_resource_limit", "Guard target inventory exceeds its supported bound.")
            result[rel] = digest(raw)
    return result


PATH_FIELDS = {"path", "grant_file", "input", "input_file", "source_path", "receipt_path", "file_path", "journal_path"}
CONTENT_FIELDS = {"content", "content_base64", "content_b64", "data", "data_base64", "body", "text", "stdout", "stderr", "raw"}
FILE_MAP_FIELDS = {"files", "file_contents", "source_files", "original_files", "proposed_files", "prior_contents"}


def _selected_argument_files(root, value, key=""):
    """Only explicit path fields are paths; filenames and content are not hints.

    Setup maps can use a filename such as ontology_profiles.py as a dictionary
    key and base64 file content as its value. Substring matching that key would
    treat the entire content as a filename and could expose it in an OSError.
    """
    if key in CONTENT_FIELDS:
        return []
    if isinstance(value, dict):
        if key in FILE_MAP_FIELDS:
            return []
        result = []
        for name, item in value.items():
            field = name + "_path" if name in {"source", "destination"} and name + "_sha256" in value else name
            result.extend(_selected_argument_files(root, item, field))
        return result
    if isinstance(value, list):
        return [path for item in value for path in _selected_argument_files(root, item, key)]
    if key not in PATH_FIELDS or not isinstance(value, str) or value == "-":
        return []
    if re.match(r"[a-zA-Z][a-zA-Z0-9+.-]*://", value):
        return []  # A selected URI is not a request to inspect a local file.
    fail(0 < len(value.encode()) <= 4096 and not any(ord(char) < 32 for char in value),
         "guard_invalid_path", "An explicit request path is malformed or exceeds its bound.", field=key)
    path = Path(value)
    if not path.is_absolute():
        path = root / path
    try:
        return [path] if path.is_file() else []
    except OSError as exc:
        raise GuardError("guard_invalid_path", "An explicit request path cannot be inspected safely.",
                         {"field": key, "errno": exc.errno}) from None


def _argument_paths(root, value, key=""):
    return {path.relative_to(root).as_posix() for path in _selected_argument_files(root, value, key)
            if path.is_relative_to(root)}


def _external_argument_context(root, value, key=""):
    found = {}
    for path in _selected_argument_files(root, value, key):
        if path.is_relative_to(root):
            continue
        fail(not any(parent.is_symlink() for parent in (path, *path.parents)), "guard_scope", "External reviewed input cannot traverse a symbolic link.")
        try:
            fail(path.stat().st_size <= 8 * 1024 * 1024, "guard_resource_limit", "Reviewed input exceeds the guard bound.")
            found[str(path)] = digest(path.read_bytes())
        except OSError as exc:
            raise GuardError("guard_invalid_path", "A reviewed external input cannot be read safely.", {"errno": exc.errno}) from None
    return found


def _accepted_publication(root, arguments):
    proposal = arguments.get("proposal", arguments.get("intent", {}).get("proposal"))
    if not isinstance(proposal, dict) or proposal.get("schema_version") != 2:
        return None
    identity = proposal.get("operation_id")
    if not isinstance(identity, str) or not re.fullmatch(r"ONTOP-[A-Za-z0-9-]{4,100}", identity):
        return None
    path = "control_records/ontology/intents/" + identity + ".json"
    if not checked_path(root, path).is_file():
        return None
    from ontology_publication import _read_intent
    intent = _read_intent(root, identity)
    fail(intent["proposal"] == proposal and ("intent" not in arguments or arguments["intent"] == intent),
         "guard_stale", "The request differs from its actual accepted publication intent.")
    return path, intent


def _context(root, selected, arguments):
    files = {"ontology-advanced.yaml", "ontology.yaml", "AGENTS.md", "SOUL.md", "ROLE.md"}
    for binding in (selected["contract"], selected["adapters"], selected["bootstrap"]):
        read_bound(root, binding)
        files.add(binding["path"])
    contract = validate_contract(json.loads(read_bound(root, selected["contract"])))
    adapters = json.loads(read_bound(root, selected["adapters"]))
    bootstrap = json.loads(read_bound(root, selected["bootstrap"]))
    fail(contract.get("schema_version") == adapters.get("schema_version") == bootstrap.get("schema_version") == 1,
         "guard_schema", "Unsupported action contract, adapter inventory or bootstrap version.")
    fail(bootstrap.get("contract") == selected["contract"] and bootstrap.get("adapters") == selected["adapters"],
         "guard_stale", "Bootstrap does not bind the selected contract and complete adapter inventory.")
    fail(set(adapters.get("families", {})) == FAMILIES, "guard_coverage", "All eight action families are required before guard enablement.")
    fail(bootstrap.get("status") == "verified" and bootstrap.get("repair"), "guard_bootstrap", "No verified immutable bootstrap and repair binding.")
    read_bound(root, bootstrap["repair"])
    files.add(bootstrap["repair"]["path"])
    for name in ("engine", "setup"):
        fail(name in bootstrap, "guard_bootstrap", "Bootstrap omits an exact guard implementation binding.", binding=name)
        read_bound(root, bootstrap[name])
        files.add(bootstrap[name]["path"])
    for family in adapters["families"].values():
        fail(isinstance(family, list) and family, "guard_coverage", "Empty action family adapter coverage.")
        for adapter in family:
            fail(isinstance(adapter, dict) and set(adapter) == {"path", "sha256", "operations"}
                 and isinstance(adapter["operations"], list) and adapter["operations"], "guard_schema", "Malformed adapter declaration.")
            read_bound(root, {key: adapter[key] for key in ("path", "sha256")})
            files.add(adapter["path"])
    shape = contract.get("shapes")
    read_bound(root, shape)
    files.add(shape["path"])
    files.update(_argument_paths(root, arguments))
    config = _json(root / "ontology-advanced.yaml")
    accepted = _accepted_publication(root, arguments)
    accepted_changes = {row["path"]: row for row in accepted[1]["proposal"]["changes"]} if accepted else {}
    if accepted:
        files.add(accepted[0])
    for binding in config.get("extensions", []):
        change = accepted_changes.get(binding["path"])
        if change and binding["sha256"] == change["expected_sha256"]:
            actual = checked_path(root, binding["path"])
            fail(actual.is_file() and digest(actual.read_bytes()) in {change["expected_sha256"], change["sha256"]},
                 "guard_stale", "Accepted extension recovery requires its exact retained pre/post bytes.", path=binding["path"])
        else:
            read_bound(root, binding)
        files.add(binding["path"])
    # Exact asserted semantics and grants are current context, never authority.
    for relative in ("ONTOLOGY/modules", "ONTOLOGY/bindings", "ONTOLOGY/extensions", "Tasks", "Roles"):
        if (root / relative).exists():
            files.add(relative)
    return contract, adapters, {**_snapshot(root, files), **_external_argument_context(root, arguments)}


def _direct_facts(root, family, operation, arguments, budget):
    """The two direct owning APIs supply real proposals/profile previews.

    All other families enter through dispatch and its actual owner readers.
    A JSON field named _semantic_state is never a source of observed facts.
    """
    facts = {"input_type": family + "-" + operation + "-request", "input_valid": True, "requested_paths": []}
    if family == "ontology" and operation in {"preview", "publish", "recover"}:
        from ontology_publication import check_proposal
        from ontology_core import load_project, OntologyError
        from ontology_lifecycle import validate_transition
        proposal = arguments.get("proposal", arguments.get("intent", {}).get("proposal"))
        fail(isinstance(proposal, dict), "guard_schema", "Ontology action requires its actual normalized publication proposal.")
        check_proposal(root, proposal)
        facts["requested_paths"] = [change["path"] for change in proposal["changes"]]
        cfg = _json(root / "ontology.yaml")
        core = set(cfg["project_files"] + cfg["binding_files"] + cfg.get("competency_files", []))
        try:
            old = load_project(root, validate=False)
            candidate = load_project(root, validate=False, _overrides={change["path"]: change["content"].encode()
                for change in proposal["changes"] if change["path"] in core})
            facts["input_valid"] = not any(row["severity"] == "error" for row in candidate.diagnostics) and not validate_transition(old.records, candidate.records)
            facts["input_valid"] &= all(source["status"] == "current" for source in candidate.sources)
        except OntologyError:
            facts["input_valid"] = False
        if proposal["schema_version"] == 2 and facts["input_valid"]:
            from ontology_advanced import load_advanced, load_extensions
            from ontology_standards import validate, infer, dataset
            overrides = {change["path"]: change["content"].encode() for change in proposal["changes"]}
            configured = load_advanced(root, required=True, _overrides=overrides)
            extensions, _, _ = load_extensions(candidate, configured, _overrides=overrides)
            # load_project already ran the complete core record validator.
            # Validate selected authored shapes over the exact RDF projection
            # without regenerating hundreds of equivalent per-record shapes.
            graph = budget.evaluate(dataset, root, graphs=["asserted", "derived", "external"], overrides=overrides)
            fail(graph.get("complete") is True and graph.get("status") == "ok", "guard_unavailable",
                 "The exact candidate dataset is unavailable; restore its selected backend before retrying.", backend=graph)
            budget.candidate_graph = graph
            checked = budget.evaluate(validate, root, triples=[row[:3] for row in graph["quads"]], overrides=overrides)
            fail(isinstance(checked, dict) and checked.get("complete") is True and checked.get("status") == "conformant" and checked.get("conforms") is True,
                 "guard_candidate_invalid", "The exact v2 candidate did not establish complete semantic conformance; resolve its selected standards findings before retrying.", backend=checked)
            facts["candidate_validation"] = {"standards": {"status": checked["status"], "context_sha256": digest(checked.get("context", {})),
                "scope": "Complete core record checks plus actual selected project SHACL over the exact candidate RDF graph."}}
            formal = any(extension.get("axioms") or extension.get("negative_assertions") for extension in extensions)
            fail(not formal or configured["profiles"].get("inference", {}).get("enabled") is True,
                 "guard_inference_required", "This guarded extension contains formal assertions; explicitly enable its inference profile before validating the action.", backend={"status": "profile_disabled"})
            if configured["profiles"].get("inference", {}).get("enabled"):
                inferred = budget.evaluate(infer, root, overrides=overrides)
                fail(isinstance(inferred, dict) and inferred.get("complete") is True and inferred.get("status") == "ok" and inferred.get("trusted") is True,
                     "guard_candidate_inconsistent", "The exact v2 candidate did not establish consistent finite inference; resolve its conflicts or unavailable profile before retrying.", backend=inferred)
                facts["candidate_validation"]["inference"] = {"status": inferred["status"], "context_sha256": digest(inferred.get("context", {}))}
        # An accepted operation may resume its exact already-written post-state.
        accepted = operation == "recover" or (root / ("control_records/ontology/intents/" + proposal["operation_id"] + ".json")).is_file()
        for change in proposal["changes"]:
            path = checked_path(root, change["path"])
            actual = digest(path.read_bytes()) if path.is_file() else None
            facts["input_valid"] &= actual == change["expected_sha256"] or accepted and actual == change["sha256"]
        return facts
    if family == "setup" and operation == "configure_profile":
        from ontology_advanced import load_advanced
        preview = arguments.get("preview", {})
        change = preview.get("change", {})
        fail(isinstance(change.get("content"), str), "guard_schema", "Profile configuration requires its actual exact preview.")
        current = load_advanced(root, required=True)
        proposed = load_advanced(root, required=True, _overrides={"ontology-advanced.yaml": change["content"].encode()})
        selected = arguments.get("profile")
        facts["requested_paths"] = [change.get("path", "")]
        facts["input_valid"] = selected in {"standards", "inference", "semantic", "workbench"} and type(arguments.get("enabled")) is bool
        facts["input_valid"] &= proposed["profiles"].get(selected, {}).get("enabled") is arguments.get("enabled")
        old_other, new_other = normalize(current), normalize(proposed)
        old_other["profiles"].pop(selected, None); new_other["profiles"].pop(selected, None)
        facts["input_valid"] &= old_other == new_other
        facts["input_valid"] &= not (selected == "standards" and arguments.get("enabled") is False)
        return facts
    raise GuardError("guard_missing_evidence", "This action requires the actual owning dispatch and its current structural readers; caller-supplied semantic state is not evidence.", {"action_id": BASE + family + ":" + operation})


def _target_type(root, path):
    """Classify actual selected paths against the current owned stores."""
    checked_path(root, path)
    if path == "ontology-advanced.yaml":
        return {"ontology-owned-artifact", "setup-owned-artifact"}
    mapping = {"MEMORY": "memory", "memory.yaml": "memory", "Tasks": "task", "TRDs": "trd",
               "Implementation_Plans": "plan", "Roles": "role", "roles": "role", "control_records/roles": "role",
               "Projects/Sys4AI-Template-Project": "template", ".sys4ai/template-update/state.json": "template",
               "depot/projects.json": "setup"}
    result = {family + "-owned-artifact" for prefix, family in mapping.items() if path == prefix or path.startswith(prefix + "/")}
    cfg = _json(root / "ontology.yaml")
    canonical = cfg["project_files"] + cfg["binding_files"] + cfg.get("competency_files", [])
    advanced = _json(root / "ontology-advanced.yaml")
    for binding in advanced.get("extensions", []):
        canonical.append(binding["path"])
        canonical.extend(row["path"] for row in _json(checked_path(root, binding["path"])).get("shapes", []))
    if path in canonical:
        result.add("ontology-owned-artifact")
    if path.startswith("Projects/") and len(Path(path).parts) >= 2 and Path(path).parts[1] not in {"Sys4AI-Template-Project", ".", ".."}:
        result.add("setup-owned-artifact")
    return result


def _semantic_triples(root, family, operation, arguments, targets, facts, action, adapters, node, contract):
    fail(isinstance(facts, dict) and set(facts) <= {"input_type", "input_valid", "requested_paths", "targetIdentity", "currentState", "nextState", "targetRevision", "transition_valid", "candidate_validation"},
         "guard_schema", "Unsupported owner observation fields.")
    triples = []
    def literal(key, value):
        term = {"value": str(value).lower() if type(value) is bool else str(value)}
        if type(value) in {bool, int}:
            term["datatype"] = "http://www.w3.org/2001/XMLSchema#" + ("boolean" if type(value) is bool else "integer")
        triples.append([node, BASE + key, term])
    literal("inputType", facts.get("input_type", "unobserved"))
    literal("inputValid", facts.get("input_valid") is True and facts.get("transition_valid", True) is True)
    requested = facts.get("requested_paths", [])
    fail(isinstance(requested, list) and all(isinstance(path, str) for path in requested), "guard_schema", "Owner target paths are malformed.")
    all_targets = list(dict.fromkeys([*targets, *requested]))
    for target in all_targets:
        literal("target", target)
        types = _target_type(root, target)
        observed_type = family + "-owned-artifact" if family + "-owned-artifact" in types else (sorted(types)[0] if types else "unclassified-artifact")
        literal("targetType", observed_type)
    for key in ("targetIdentity", "currentState", "nextState", "targetRevision"):
        if key in facts:
            literal(key, facts[key])
    observed_capabilities = set()
    for binding in adapters["families"][family]:
        if operation not in binding["operations"]:
            continue
        source = read_bound(root, {key: binding[key] for key in ("path", "sha256")})
        tree = ast.parse(source)
        declarations = []
        for statement in tree.body:
            if isinstance(statement, ast.Assign) and any(isinstance(target, ast.Name) and target.id == "ONTOLOGY_GUARDED_ACTIONS" for target in statement.targets):
                declarations = ast.literal_eval(statement.value)
        # Ontology publication uses direct checks rather than the generic wrapper.
        declared = operation in declarations or "Store." + operation in declarations
        if binding["path"] == ".agents/skills/ontology/scripts/ontology_publication.py":
            declared = operation in {"preview", "publish", "recover"} and any(isinstance(n, ast.FunctionDef) and n.name == operation for n in tree.body)
        provider_family = PROVIDERS.get(binding["path"])
        if declared and provider_family:
            observed_capabilities.add(BASE + "capability:" + CAPABILITIES[provider_family])
    for capability in sorted(observed_capabilities):
        triples.append([node, BASE + "requiredCapability", capability])
    present = 0
    for name in action["governing_sources"]:
        path = checked_path(root, name)
        if path.is_file() and path.read_bytes().strip():
            present += 1
            source = BASE + "source:" + digest({"path": name, "sha256": digest(path.read_bytes())})
            triples.extend([[node, BASE + "governingSource", source], [source, BASE + "sourcePath", {"value": name}],
                            [source, BASE + "sourceDigest", {"value": digest(path.read_bytes())}]])
    literal("governingSourceCount", present)
    # The shared delivered shape defines observed facts. The selected action
    # adds its declared type/capability and lifecycle constraints as SHACL data.
    def quoted(value):
        return json.dumps(value, ensure_ascii=False)
    properties = ["sh:path action:inputType; sh:hasValue " + quoted(action["input_type"]),
                  "sh:path action:targetType; sh:in (" + quoted(action["target_type"]) + ")",
                  "sh:path action:requiredCapability; sh:hasValue <" + action["capability"] + ">"]
    if action["lifecycle"]:
        lifecycle = contract["lifecycles"][action["lifecycle"]]
        transitions = lifecycle["transitions"]
        states = " ".join(quoted(state) for state in transitions)
        allowed = transitions.get(facts.get("currentState"), [])
        if family != "task" or facts.get("currentState") not in {"completed", "cancelled", "close-old-task"}:
            allowed = list(dict.fromkeys([facts.get("currentState", "unobserved"), *allowed]))
        properties += ["sh:path action:targetIdentity; sh:minCount 1; sh:maxCount 1; sh:pattern " + quoted(lifecycle["identity_pattern"]),
                       "sh:path action:targetRevision; sh:minCount 1; sh:maxCount 1; sh:datatype xsd:integer; sh:minInclusive 1",
                       "sh:path action:currentState; sh:minCount 1; sh:maxCount 1; sh:in (" + states + ")",
                       "sh:path action:nextState; sh:minCount 1; sh:maxCount 1; sh:in (" + " ".join(quoted(state) for state in allowed) + ")"]
    shape = "\naction:SelectedActionShape a sh:NodeShape; sh:targetNode <" + node + ">;\n  " + ";\n  ".join("sh:property [ " + value + " ]" for value in properties) + " .\n"
    return triples, shape


class Decision:
    def __init__(self, root, family, operation, arguments, targets, observed=None):
        self.root, self.family, self.operation = root, family, operation
        self.action_id = BASE + family + ":" + operation
        self.arguments, self.targets = arguments, tuple(targets)
        self.live_arguments = None
        self.selected = profile(root)
        self.lock_checked = False
        self.request_sha256 = digest(arguments)
        self.pre = self.context = self.backend = None
        if self.selected is None:
            return
        budget = _GuardBudget(root)
        fail("_semantic_state" not in arguments, "guard_missing_evidence", "Caller-supplied semantic state is not current owning-helper evidence.", action_id=self.action_id)
        fail(family in FAMILIES, "guard_unsupported", "Unsupported guarded action family.", action_id=self.action_id)
        contract, adapters, self.context = _context(root, self.selected, arguments)
        bootstrap = json.loads(read_bound(root, self.selected["bootstrap"]))
        engine = bootstrap["engine"]
        fail(checked_path(root, engine["path"]).resolve() == Path(__file__).resolve()
             and engine["sha256"] == ENGINE_SOURCE_SHA256,
             "guard_stale", "Loaded guard engine is not the selected project's exact installed engine.", action_id=self.action_id)
        definitions = contract.get("actions", []) + contract.get("optional_actions", [])
        matches = [item for item in definitions if item.get("family") == family and item.get("operation") == operation]
        fail(len(matches) == 1, "guard_ambiguous" if len(matches) > 1 else "guard_unsupported",
             "Action must resolve to exactly one current semantic contract.", action_id=self.action_id)
        fail(any(operation in item["operations"] for item in adapters["families"][family]), "guard_coverage", "No current adapter binds this operation.", action_id=self.action_id)
        fail(len(targets) == len(set(targets)), "guard_ambiguous", "Duplicate action targets are ambiguous.", action_id=self.action_id)
        self.pre = _snapshot(root, targets)
        facts = observed if observed is not None else _direct_facts(root, family, operation, arguments, budget)
        self.request_sha256 = digest({"arguments": arguments, "observations": facts})
        self.facts = facts
        node = self.action_id + ":request:" + self.request_sha256
        triples = [[node, "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", BASE + "Request"],
                   [node, BASE + "family", {"value": family}], [node, BASE + "operation", {"value": operation}],
                   [node, BASE + "requestDigest", {"value": self.request_sha256}],
                   [node, BASE + "targetDigest", {"value": digest(self.pre)}]]
        observed_triples, selected_shape = _semantic_triples(root, family, operation, arguments, targets, facts, matches[0], adapters, node, contract)
        triples.extend(observed_triples)
        try:
            from ontology_standards import validate
        except ImportError as exc:
            raise GuardError("guard_unavailable", "Enabled action guards require the provisioned standards backend.", {"action_id": self.action_id}) from exc
        shapes = read_bound(root, contract["shapes"]).decode() + selected_shape
        proposal = arguments.get("proposal", arguments.get("intent", {}).get("proposal")) if family == "ontology" else None
        candidate_overrides = {change["path"]: change["content"].encode() for change in proposal["changes"]} if isinstance(proposal, dict) and proposal.get("schema_version") == 2 else None
        from ontology_advanced import load_advanced
        configured = load_advanced(root, required=True, _overrides=candidate_overrides)
        has_selected_shapes = any(json.loads((candidate_overrides or {}).get(ref["path"], checked_path(root, ref["path"]).read_bytes())).get("shapes") for ref in configured["extensions"])
        if has_selected_shapes:
            # The standards interface applies selected project shapes as well
            # as action shapes. Supply their actual authoring data so a valid
            # project shape does not fail against an action-only graph.
            from ontology_standards import dataset
            graph = getattr(budget, "candidate_graph", None)
            if graph is None:
                graph = budget.evaluate(dataset, root, graphs=["asserted", "derived", "external"], overrides=candidate_overrides)
            fail(graph.get("complete") is True and graph.get("status") == "ok", "guard_unavailable", "Selected shape data could not be read completely; restore its backend before retrying.", backend=graph)
            triples.extend(row[:3] for row in graph["quads"])
        try:
            self.backend = budget.evaluate(validate, root, triples=triples, shapes=shapes, overrides=candidate_overrides)
        except GuardError:
            raise
        except Exception as exc:
            raise GuardError("guard_processing_failure", "The enabled validation backend failed; no mutation was dispatched.",
                             {"action_id": self.action_id, "failure_type": type(exc).__name__}) from exc
        backend_status = self.backend.get("status") if isinstance(self.backend, dict) else None
        condition = backend_status if isinstance(backend_status, str) and re.fullmatch(r"[a-z_]{1,60}", backend_status) else "processing_failure"
        fail(isinstance(self.backend, dict) and backend_status == "conformant" and self.backend.get("complete") is True,
             "guard_" + condition,
             "Enabled semantic validation did not establish conformance; restore the backend or resolve its findings before retrying.",
             action_id=self.action_id, contract=self.selected["contract"],
             governing_versions={name: self.context.get(name) for name in matches[0]["governing_sources"]}, backend=self.backend)
        # The backend may have run while a governing file or target changed.
        self.recheck()
        budget.check()
        self.evaluation_seconds = round(budget.clock() - budget.started, 4)
        self.evaluation_budget_seconds = budget.seconds

    def recheck(self, *, targets=True):
        try:
            return self._recheck(targets=targets)
        except GuardError as exc:
            exc.details.setdefault("action_id", self.action_id)
            if self.selected:
                exc.details.setdefault("contract", self.selected["contract"])
            raise

    def _recheck(self, *, targets=True):
        if self.selected is None:
            fail(profile(self.root) is None, "guard_stale", "Guard profile changed before dispatch.")
            return
        fail(profile(self.root) == self.selected, "guard_stale", "Guard profile changed before dispatch.", action_id=self.action_id)
        fail(hashlib.sha256(Path(__file__).read_bytes()).hexdigest() == ENGINE_SOURCE_SHA256,
             "guard_stale", "Loaded guard-engine bytes changed after import; the prior decision cannot continue.", action_id=self.action_id)
        _, _, current = _context(self.root, self.selected, self.arguments)
        def retained(values):
            # An owning transaction checks its selected writes against its own
            # exact accepted pre/post digests.  Keep every other source bound.
            accepted = _accepted_publication(self.root, self.arguments) if self.family == "ontology" else None
            own_new_intent = accepted[0] if accepted and self.lock_checked and accepted[0] not in self.context else None
            return {key: value for key, value in values.items() if key != own_new_intent and (targets or not any(
                key == target or key.startswith(target.rstrip("/") + "/") for target in self.targets))}
        fail(retained(current) == retained(self.context), "guard_stale", "Ontology, rules, source or authority context changed before dispatch.", action_id=self.action_id)
        current_arguments = normalize(self.live_arguments) if self.live_arguments is not None else self.arguments
        def request_fields(values):
            # Setup's record is its mutable owned transaction state, not a new
            # request; its original bytes stay in the target/receipt snapshots.
            return {key: value for key, value in values.items() if not (
                self.family == "setup" and self.lock_checked and key == "record")}
        fail(digest(request_fields(current_arguments)) == digest(request_fields(self.arguments)), "guard_stale", "Action arguments changed before dispatch.", action_id=self.action_id)
        if targets:
            fail(_snapshot(self.root, self.targets) == self.pre, "guard_stale", "Action target changed before its owning lock was acquired.", action_id=self.action_id)

    def finish(self, receipt):
        if self.selected is None:
            return receipt
        evidence = {"schema_version": 1, "action_id": self.action_id, "request_sha256": self.request_sha256,
                    "semantic_status": "conformant", "context_sha256": digest(self.context),
                    "backend_context": self.backend.get("context"), "pre_state_sha256": digest(self.pre),
                    "post_state_sha256": digest(_snapshot(self.root, self.targets)),
                    "owning_helper": "returned", "authorization": "retained_in_owning_helper",
                    "execution_and_verification": "see_owning_helper_receipt", "lock_rechecked": self.lock_checked}
        evidence["observations_sha256"] = digest(self.facts)
        evidence["evaluation_budget_seconds"] = self.evaluation_budget_seconds
        # Publication previews are hashed and recomputed before dispatch.
        # Keep measured time in actual execution receipts, not exact review
        # identity: equivalent semantic previews must retain identical hashes.
        if not (self.family == "ontology" and self.operation == "preview"):
            evidence["evaluation_seconds"] = self.evaluation_seconds
        if "candidate_validation" in self.facts:
            evidence["candidate_validation"] = self.facts["candidate_validation"]
        if isinstance(receipt, dict):
            return dict(receipt, ontology_guard=evidence)
        if isinstance(receipt, tuple) and receipt and isinstance(receipt[0], dict):
            return (dict(receipt[0], ontology_guard=evidence), *receipt[1:])
        return receipt


def begin_action(root, family, operation, arguments, targets=(), *, _observed=None):
    root = Path(root).absolute()
    try:
        normalized = normalize(arguments)
        fail(isinstance(normalized, dict), "guard_schema", "Action arguments must be an object.")
        fail(len(encoded(normalized)) <= 8 * 1024 * 1024, "guard_resource_limit", "Action request exceeds the guard input bound.")
        decision = Decision(root, family, operation, normalized, list(targets), _observed)
    except GuardError as exc:
        exc.details.setdefault("action_id", BASE + family + ":" + operation)
        try:
            current = profile(root)
        except GuardError:
            current = None  # Retain the original failed configuration diagnostic.
        if current:
            exc.details.setdefault("contract", current["contract"])
        else:
            configuration = root / "ontology-advanced.yaml"
            if configuration.is_file() and not configuration.is_symlink():
                exc.details.setdefault("configuration", {"path": "ontology-advanced.yaml", "sha256": digest(configuration.read_bytes())})
        raise
    decision.live_arguments = arguments
    return decision


def checkpoint(*, targets=True):
    """Called by owning lock/replace helpers; never acquires a competing lock."""
    for decision in ACTIVE.get():
        decision.recheck(targets=targets and not decision.lock_checked)
        if targets:
            decision.lock_checked = True


def require_adapter(decision, actual):
    if decision.selected is not None:
        fail(isinstance(actual, str) and Path(actual).is_file(), "guard_stale", "The executing owning helper has no current file binding.", action_id=decision.action_id, contract=decision.selected["contract"])
        adapters = json.loads(read_bound(decision.root, decision.selected["adapters"]))
        checksum = digest(Path(actual).read_bytes())
        fail(any(decision.operation in item["operations"] and item["sha256"] == checksum for item in adapters["families"][decision.family]),
             "guard_stale", "The executing helper differs from the selected current dispatch binding.", action_id=decision.action_id, contract=decision.selected["contract"])


def dispatch(function, family, operation, root, arguments, targets):
    try:
        facts = schema_check(function.__globals__, family, operation, root, arguments)
    except GuardError as exc:
        exc.details.setdefault("action_id", BASE + family + ":" + operation)
        current = profile(root)
        if current:
            exc.details.setdefault("contract", current["contract"])
        raise
    decision = begin_action(root, family, operation, arguments, targets, _observed=facts)
    require_adapter(decision, function.__globals__.get("__file__"))
    token = ACTIVE.set((*ACTIVE.get(), decision))
    try:
        return decision.finish(function())
    finally:
        ACTIVE.reset(token)


def schema_check(namespace, family, operation, root, arguments):
    """Run the owner's structural readers before semantic evaluation, without auth."""
    normalize(arguments)
    fail("_semantic_state" not in arguments, "guard_missing_evidence", "Caller-supplied semantic state is not owning-helper evidence.")
    root = Path(root).absolute()
    facts = {"input_type": family + "-" + operation + "-request", "input_valid": True, "requested_paths": []}
    def relative(path):
        selected = Path(path).absolute()
        fail(selected.is_relative_to(root), "guard_scope", "Actual owning target escapes the selected project.")
        return selected.relative_to(root).as_posix()
    if family == "memory":
        if operation in {"transact", "capture", "recover"}:
            from memory_publish import validate_payload_structure
            payload = arguments.get("payload")
            recovering = operation == "recover"
            if recovering:
                journal = namespace["_read_journal"](root, str(arguments["journal_path"]))
                payload = journal["payload"]
            validate_payload_structure(payload)
            from memory_core import load_config, parse_record, validate_record
            config = load_config(root)
            if not recovering:
                journal_path = config["state"]["maintenance"] + "/transactions/" + payload["operation_id"] + ".json"
                if checked_path(root, journal_path).is_file():
                    from memory_recovery import _read_journal
                    accepted = _read_journal(root, journal_path)
                    recovering = accepted["payload"] == payload
            next_states = []
            for change in payload["changes"]:
                value = validate_record(parse_record(change["content"]), config["project"]["id"])
                meta = value["metadata"]
                next_states.append(meta["state"])
                facts["requested_paths"].append(change["path"])
                facts["input_valid"] &= change["path"] == "MEMORY/" + meta["id"] + ".md" and digest(change["content"].encode()) == change["reviewed_record_sha256"]
                target = checked_path(root, change["path"])
                previous = parse_record(target.read_bytes())["metadata"] if target.is_file() else None
                if previous:
                    facts["input_valid"] &= previous["id"] == meta["id"]
                current_state = previous["state"] if previous else "absent"
                actual_sha = digest(target.read_bytes()) if target.is_file() else None
                facts["input_valid"] &= actual_sha == change["expected_sha256"] or (recovering and actual_sha == change["reviewed_record_sha256"])
                transition = payload["operation"]
                if not recovering:
                    if transition == "publish":
                        facts["input_valid"] &= current_state in {"absent", "draft"} and meta["state"] == "active"
                    elif transition == "supersede":
                        facts["input_valid"] &= (current_state == "active" and meta["state"] == "superseded") or (current_state in {"absent", "draft"} and meta["state"] == "active")
                    elif transition == "retract":
                        facts["input_valid"] &= current_state == "active" and meta["state"] == "retracted"
                    elif transition == "redact":
                        facts["input_valid"] &= previous is not None
                if meta["state"] == "active":
                    from memory_evidence import validate_publication_evidence
                    validate_publication_evidence(root, value, config)
            if payload["operation"] == "publish":
                facts["input_valid"] &= next_states == ["active"]
            elif payload["operation"] == "supersede":
                facts["input_valid"] &= next_states.count("active") == 1 and next_states.count("superseded") == len(next_states) - 1 and len(next_states) > 1
            elif payload["operation"] == "retract":
                facts["input_valid"] &= next_states == ["retracted"]
        elif operation == "propose":
            namespace["validate_record"](arguments["record"], namespace["load_config"](root)["project"]["id"])
            facts["input_valid"] &= arguments["record"]["metadata"]["state"] == "draft"
            output = arguments.get("output")
            if output is not None:
                facts["input_valid"] &= not str(output).startswith(("MEMORY/", ".sys4ai/"))
        elif operation == "set_capture":
            fail(type(arguments["enabled"]) is bool, "guard_schema", "Capture setting must be Boolean.")
        elif operation in {"reindex", "recover_reindex"}:
            config = namespace["load_config"](root)
            facts["input_valid"] &= config["project"]["id"] == _json(root / "ontology.yaml")["project"]["id"]
            if operation == "recover_reindex":
                identity = arguments["operation_id"]
                fail(isinstance(identity, str) and re.fullmatch(r"[0-9a-f]{32}", identity), "guard_schema", "Malformed memory maintenance identity.")
                journal = _json(checked_path(root, config["state"]["maintenance"] + "/backend-" + identity + ".json"))
                facts["input_valid"] &= journal.get("operation_id") == identity and journal.get("status") not in namespace["TERMINAL"]
    elif family == "task":
        if "tasks_root" in arguments:
            facts["requested_paths"] = [relative(arguments["tasks_root"])]
        if operation in {"command_new", "command_intake"}:
            payload = arguments.get("payload", arguments.get("raw_payload"))
            if operation == "command_intake":
                payload = {key: value for key, value in payload.items() if key != "intake_actor"}
            namespace["validate_new_payload"](payload)
        elif operation == "response_transaction":
            catalog = namespace["scan_catalog"](arguments["tasks_root"])
            namespace["require_valid_catalog"](catalog)
            state, _ = namespace["resolve_task"](arguments["selector"], catalog)
            payload = arguments["raw_payload"]
            if arguments["command"] == "orchestrate":
                namespace["require_object_keys"](payload, required={"event", "response"}, optional=set(), label="orchestration payload")
                fail(state.get("schema_version") == 2, "guard_schema", "Typed orchestration requires an explicitly enabled schema-2 Task.")
                event = payload["event"]
                orch = namespace["orch"]
                orch.keys(event, ("event_id", "actor", "execution_id", "generation", "kind", "data"))
                orch.validate_event_data(event["kind"], event["data"])
                current = state["orchestration"]
                starting = event["kind"] == "manager.reserve" and current["stage"] in {"unassigned", "finished"}
                if starting:
                    facts["input_valid"] &= event["generation"] == 1 and event["execution_id"] is not None and event["execution_id"] != current["execution_id"]
                    facts["input_valid"] &= state["status"] == "open" and not orch.unresolved(current)
                else:
                    facts["input_valid"] &= event["generation"] == current["generation"] and event["execution_id"] == current["execution_id"]
                facts["input_valid"] &= not any(row["event_id"] == event["event_id"] for row in current["events"])
                if "assignment_id" in event["data"] and event["kind"] not in {"manager.reserve", "assignment.reserve"}:
                    facts["input_valid"] &= event["data"]["assignment_id"] in current["assignments"]
                if event["kind"] == "manager.activate":
                    facts["input_valid"] &= current["stage"] == "receipt_recorded" and event["data"]["assignment_id"] == current["manager_id"]
                payload = payload["response"]
            checked = namespace["validate_response_payload"](payload, arguments["command"], state, root)
            command = arguments["command"]
            target = {"pause": "paused", "complete": "completed", "cancel": "cancelled", "reopen": "open", "close-old-task": "close-old-task"}.get(command, checked.get("status_after") or state["status"])
            facts.update(targetIdentity=state["task_id"], currentState=state["status"], nextState=target, targetRevision=state["revision"])
            facts["transition_valid"] = state["status"] not in namespace["TERMINAL"] or command == "reopen" and state["status"] == "completed"
            facts["input_valid"] &= type(arguments["expected_revision"]) is int and arguments["expected_revision"] == state["revision"]
        elif operation == "command_reconcile":
            # The existing validator combines schema and current confirmation.
            # Validate the structural copy here; the untouched actual request
            # still passes through the owner's confirmation check after guard.
            structural = dict(arguments["payload"])
            structural["user_authorized"] = True
            namespace["validate_reconcile_payload"](structural)
    elif family == "trd":
        if "self" in arguments:
            facts["requested_paths"] = [relative(arguments["self"].folder)]
        payload = arguments.get("payload")
        if operation in {"create", "update"}:
            fail(isinstance(payload, dict) and bool(payload) and set(payload) <= {"title", "body"}
                 and (operation != "create" or set(payload) == {"title", "body"}), "guard_schema", "TRD authoring accepts its exact title/body schema.")
            if "title" in payload:
                namespace["text_value"](payload["title"], "title", 160)
            if "body" in payload:
                namespace["validate_body"](namespace["normalized_body"](payload["body"]), allow_legacy_open_questions=False)
        elif operation == "set_status":
            fail(isinstance(arguments["status"], str), "guard_schema", "TRD status must be text.")
        if "selector" in arguments:
            store = arguments["self"]
            selected = store.resolve(arguments["selector"], store.read()[0])
            facts.update(targetIdentity=selected.meta["trd_id"], currentState=selected.meta["status"], targetRevision=selected.meta["revision"])
            if operation == "set_status":
                target = arguments["status"]
                facts["nextState"] = target
            if "expected" in arguments:
                facts["input_valid"] &= arguments["expected"] == selected.sha256
    elif family == "role":
        if operation == "create_role":
            namespace["validate_role_name"](arguments["args"].name)
            namespace["render_role_bundle"](arguments["args"])
        elif operation == "transition_apply":
            namespace["validate_preview"](arguments["preview"], root)
        elif operation == "case_rename_apply":
            namespace["validate_case_rename_preview"](arguments["preview"], root)
        elif operation in {"reindex", "publish_index"}:
            catalog = namespace["build_catalog"](root)
            facts["input_valid"] &= not catalog.invalid_roles
            if arguments.get("expected_fingerprint") is not None:
                facts["input_valid"] &= catalog.fingerprint == arguments["expected_fingerprint"]
    elif family == "plan":
        if "context" in arguments:
            facts["requested_paths"] = [relative(arguments["context"].plans_root)]
        if operation == "handle_create":
            raw = namespace["read_input"](arguments["args"].input)
            namespace["guard_prohibited_content"](raw)
            namespace["normalize_plan_input"](raw, arguments["context"])
        elif operation == "mutate_existing_plan":
            fail(type(arguments["expected_revision"]) is int and arguments["expected_revision"] > 0,
                 "guard_schema", "Plan mutation requires a positive exact revision.")
            namespace["parse_expected_hash"](arguments["expected_sha256"])
            selected = namespace["select_plan"](arguments["context"], arguments["selector"])
            facts["input_valid"] &= arguments["expected_revision"] == selected.plan["revision"] and arguments["expected_sha256"] == selected.sha256
            facts.update(targetIdentity=selected.plan["plan_id"], currentState=selected.plan["status"], targetRevision=selected.plan["revision"])
        elif operation in {"handle_update", "handle_update_phase", "handle_update_task", "handle_record_evidence"}:
            args = arguments["args"]
            raw = namespace["read_input"](args.input)
            namespace["guard_prohibited_content"](raw)
            fail(isinstance(raw, dict), "guard_schema", "Plan update requires a structured request.")
            selected = namespace["select_plan"](arguments["context"], args.selector)
            facts["input_valid"] &= args.expect_revision == selected.plan["revision"] and args.expect_sha256 == selected.sha256
            facts.update(targetIdentity=selected.plan["plan_id"], currentState=selected.plan["status"], targetRevision=selected.plan["revision"])
            if operation != "handle_record_evidence":
                command, prefix = {"handle_update": ("update", "BASELINE"), "handle_update_phase": ("update-phase", "PHASE"), "handle_update_task": ("update-task", "TASK")}[operation]
                patch, *_ = namespace["_operation_controls"](raw, command=command, allowed_patch_fields=namespace[prefix + "_PATCH_FIELDS"])
                namespace["validate_patch_value_types"](patch, namespace[prefix + "_PATCH_TYPES"], command)
                collection = "phases" if operation == "handle_update_phase" else "tasks" if operation == "handle_update_task" else None
                if collection:
                    key = "phase_id" if collection == "phases" else "task_id"
                    target = namespace["_find_record"](selected.plan[collection], key, getattr(args, key), collection)
                    if "status" in patch:
                        facts["input_valid"] &= patch["status"] == target["status"] or patch["status"] in namespace["TASK_TRANSITIONS"].get(target["status"], set())
                if patch and operation != "handle_update_task":
                    facts["input_valid"] &= selected.plan["status"] not in {"completed", "retired", "cancelled"}
            else:
                collection = "tasks" if namespace["TASK_ID_RE"].fullmatch(args.target_id) else "requirements"
                key = "task_id" if collection == "tasks" else "requirement_id"
                namespace["_find_record"](selected.plan[collection], key, args.target_id, "evidence target")
                facts["input_valid"] &= raw.get("evidence_type", "planned_check") == "planned_check" or selected.plan["status"] == "in_progress"
        elif operation == "handle_set_status":
            args = arguments["args"]
            selected = namespace["select_plan"](arguments["context"], args.selector)
            state = selected.plan["status"]
            facts.update(targetIdentity=selected.plan["plan_id"], currentState=state, nextState=args.status_value, targetRevision=selected.plan["revision"])
            revision = getattr(args, "expect_revision", getattr(args, "expected_revision", None))
            checksum = getattr(args, "expect_sha256", getattr(args, "expected_sha256", None))
            facts["input_valid"] &= revision == selected.plan["revision"] and checksum == selected.sha256
    elif family == "setup":
        if "destination" in arguments:
            facts["requested_paths"] = [relative(arguments["destination"])]
        if operation == "run_initialization":
            namespace["validate_identity"](arguments["project_id"], arguments["project_name"], arguments["purpose"])
            fail(arguments["mode"] in {"create", "prepare-existing"}, "guard_schema", "Unsupported setup mode.")
        elif operation == "run_module_adoption":
            record = arguments["record"]
            fail(isinstance(record, dict) and isinstance(arguments["previous_raw"], bytes), "guard_schema", "Module adoption requires the current receipt and exact original bytes.")
            receipt = arguments["destination"] / namespace["RECORD"]
            facts["input_valid"] &= record.get("status") == "completed" and record.get("completed_stages") == namespace["STAGES"]
            facts["input_valid"] &= receipt.is_file() and receipt.read_bytes() == arguments["previous_raw"]
            selected = arguments.get("module_id", namespace["LEARNING_MODULE"])
            facts["input_valid"] &= selected in {namespace["LEARNING_MODULE"], namespace["ONTOLOGY_MODULE"], namespace["ADVANCED_MODULE"]}
    elif family == "template":
        if operation == "update":
            fail(arguments["command"] in {"check", "apply"}, "guard_schema", "Unsupported Template operation.")
        elif operation == "recover":
            fail(isinstance(arguments["pending"], dict), "guard_schema", "Template recovery requires the exact pending record.")
        if arguments.get("retire_collection"):
            state_path = root / ".sys4ai/template-update/state.json"
            state = _json(state_path) if state_path.is_file() else {}
            # Retirement must refer to an actually recorded collection, not an
            # arbitrary name supplied as a semantic capability.
            facts["input_valid"] &= arguments["retire_collection"] in state.get("collections", {})
    return facts

"""Scoped, read-only readiness. Observations confer no mutation authority."""
from datetime import datetime, timezone
from pathlib import Path

from ontology_core import OntologyError, load_project, require, sha256, safe_path

PROFILES = {"standards", "inference", "semantic", "guards", "workbench"}
PRODUCTS = {"compile", "build-wiki", "link-memory"}


def arguments(parser, *, advanced=False):
    parser.add_argument("--scope", choices=("canonical", "selected"), default="selected")
    parser.add_argument("--level", choices=("static", "operational"), default="static")
    parser.add_argument("--require", action="append", default=[], choices=sorted(PROFILES if advanced else PRODUCTS))
    if advanced:
        parser.add_argument("--workbench-url", help="Explicit http://127.0.0.1:PORT origin; never a bootstrap URL.")


def aggregate(result, root, scope, level, components, context=None):
    require(scope in {"canonical", "selected"} and level in {"static", "operational"},
            "invalid_assessment", "Select canonical/selected scope and static/operational level.")
    failures = [name for name, value in components.items() if value.get("required") and not value.get("ready")]
    status = result.get("status") if result.get("status") in {"absent", "invalid"} else "degraded" if failures else "ready"
    result.setdefault("project_id", (context or {}).get("project_id"))
    result.update(health_schema_version=2, status=status, aggregate=status, ready=status == "ready",
                  assessment={"project_root": str(Path(root).absolute()), "scope": scope, "level": level,
                              "observed_at": datetime.now(timezone.utc).isoformat(),
                              "input_versions": context or {}, "components": components,
                              "failed_required": failures}, mutated=False)
    return result


def guard_health(root):
    from ontology_guards import profile, _context, GuardError, fail
    from ontology_guard_setup import coverage_manifest
    from ontology_profiles import health
    try:
        selected = profile(root)
        if selected is None:
            return {"status": "disabled", "enabled": False, "observed_dispatch": "not_exercised"}
        contract, adapters, inputs = _context(Path(root), selected, {})
        current = coverage_manifest(root, contract)
        fail(adapters == current, "guard_coverage", "Current dispatch declarations differ from the complete bound adapter inventory.")
        backend = health(root)
        ready = backend["status"] == "ready"
        return {"status": "ready" if ready else "backend_unavailable", "enabled": True,
                "integrity": "current", "families": sorted(current["families"]),
                "adapters": current, "inputs": inputs, "backend": backend,
                "observed_dispatch": "not_exercised", "coverage": "declared owning helper dispatch only",
                "next_operation": None if ready else "profile-setup standards"}
    except (GuardError, OntologyError, OSError, ValueError, KeyError, TypeError, SyntaxError) as exc:
        return {"status": "unavailable", "enabled": True, "observed_dispatch": "not_exercised",
                "diagnostics": [{"code": getattr(exc, "code", "invalid_guard"), "message": str(exc)[:1000],
                                 "details": getattr(exc, "details", {})}], "next_operation": "guard preview/repair"}


def advanced_health(root, *, scope="selected", level="static", required=(), workbench_url=None):
    from ontology_advanced import load_advanced
    from ontology_profiles import health
    from ontology_semantic import health as semantic_health
    from ontology_workbench import assess_service
    require(set(required) <= PROFILES, "invalid_assessment", "Unknown required advanced component.")
    try:
        cfg = load_advanced(root)
        project = load_project(root, validate=False)
        context = project.context()
        config_path = safe_path(root, "ontology-advanced.yaml", must_exist=False)
        context = {**context, "advanced_config_sha256": sha256(config_path) if config_path.exists() else None}
        profiles = {"standards": health(root), "inference": health(root, "inference"),
                    "semantic": semantic_health(root), "guards": guard_health(root)}
        enabled = bool(cfg and cfg["profiles"].get("workbench", {}).get("enabled"))
        profiles["workbench"] = assess_service(root, workbench_url) if workbench_url else {
            "status": "ready" if enabled else "disabled", "enabled": enabled,
            "service_state": "not_assessed", "running": None, "mode": "on_demand",
            "observed_operation": "not_exercised"}
        components = {}
        for name, detail in profiles.items():
            selected = bool(cfg and cfg["profiles"].get(name, {}).get("enabled"))
            needed = name in required or (scope == "selected" and selected) or (name == "workbench" and bool(workbench_url))
            components[name] = {"required": needed, "enabled": selected,
                                "ready": detail["status"] == "ready", "status": detail["status"],
                                "observed_operation": "not_exercised"}
        components["canonical"] = {"required": True, "ready": not any(d["severity"] == "error" for d in project.diagnostics)
                                    and all(s["status"] == "current" for s in project.sources)}
        if level == "operational":
            from ontology_standards import query, validate, infer
            from ontology_semantic import search
            for name, component in components.items():
                if not component["required"] or name == "canonical":
                    continue
                observed = None
                if component["ready"]:
                    if name == "standards":
                        observed = {"query": query(root, "ASK { ?s ?p ?o }"), "validation": validate(root)}
                        component["ready"] = all(x.get("complete") and x.get("status") not in {"violation", "processing_failure"} for x in observed.values())
                    elif name == "inference":
                        observed = infer(root)
                        component["ready"] = observed.get("complete") is True and observed.get("status") == "ok" and observed.get("trusted") is True
                    elif name == "semantic":
                        try:
                            observed = search(project, "recollections", limit=3)
                            component["ready"] = observed.get("semantic", {}).get("used") is True
                        except OntologyError as exc:
                            observed = {"status": exc.code, "complete": False, "diagnostics": [exc.as_dict()]}
                            component["ready"] = False
                    elif name == "guards":
                        from ontology_guards import profile, read_bound, GuardError
                        from ontology_guard_setup import _backend
                        import json
                        try:
                            contract = json.loads(read_bound(root, profile(root)["contract"]))
                            observed = _backend(root, read_bound(root, contract["shapes"]).decode())
                            component["ready"] = observed.get("complete") is True
                            component["dispatch"] = "not_exercised; read-only validator probe only"
                        except GuardError as exc:
                            component["ready"] = False
                            observed = {"status": exc.code, "diagnostics": [{"message": str(exc)[:1000]}]}
                    elif name == "workbench":
                        component["ready"] = bool(workbench_url) and profiles[name].get("running") is True
                        observed = profiles[name]
                component["observed_operation"] = observed or "not_exercised"
        result = {"operation": "advanced-health", "implemented": True, "profiles": profiles}
        if cfg is None:
            result["status"] = "absent"
        return aggregate(result, root, scope, level, components, context)
    except OntologyError as exc:
        return aggregate({"operation": "advanced-health", "status": "invalid", "error": exc.as_dict()},
                         root, scope, level, {"configuration": {"required": True, "ready": False}})


def maintenance_status(root):
    """Report the current dependency closure; this function performs no repair."""
    from ontology import health
    core = health(root)
    advanced = advanced_health(root)
    pending = []
    for result in (core, advanced):
        for name, component in result["assessment"]["components"].items():
            if component.get("required") and not component.get("ready"):
                pending.append({"component": name, "status": component.get("status", "invalid"),
                                "next_operation": component.get("next_operation") or {
                                    "semantic": "build-semantic-index", "standards": "profile-setup standards",
                                    "inference": "profile-setup standards", "guards": "guard preview/repair",
                                    "canonical": "inspect source/configuration diagnostics"}.get(name, "inspect selected component")})
    # No advanced companion is a valid first-release configuration.
    static_ready = core["ready"] and (advanced["ready"] or advanced["status"] == "absent")
    return {"static_ready": static_ready, "operational_readiness": "not_exercised",
            "maintenance_pending": pending, "required_operations": sorted({x["next_operation"] for x in pending}),
            "assessment": {"core": core["assessment"], "advanced": advanced["assessment"]},
            "mutated": False}

"""Read-only adapters to the installed memory package and explicit derived links."""
import json
import os
import re
import subprocess
import sys

from ontology_core import OntologyError, canonical_bytes, read_bytes, read_json, require, safe_path, sha256
from ontology_retrieval import limits, normalize, project, query_text, ranked


def _installed(p, operation, **arguments):
    """Call current installed public APIs in a separate import namespace."""
    scripts = safe_path(p.root, ".agents/skills/memory/scripts", must_exist=False)
    if not scripts.is_dir() or not safe_path(p.root, ".agents/skills/memory/scripts/memory.py", must_exist=False).is_file():
        return {"status": "unavailable", "results": [], "limitations": ["Installed project memory interface is unavailable."]}
    code = '''import json,sys
sys.dont_write_bytecode=True
sys.path.insert(0,sys.argv[1])
from memory_core import MemoryError,load_config,load_record,load_records
from memory_search import search
data=json.load(sys.stdin)
try:
 config=load_config(data['root'],optional=True)
 if config is None:
  result={'status':'unconfigured','results':[],'limitations':['No project memory configuration.']}
 elif config['project']['id']!=data['project_id']:
  result={'status':'identity_mismatch','results':[],'limitations':['Memory and ontology project identities differ.']}
 elif data['operation']=='search':
  result=search(data['root'],data['query'],config=config,packet=data.get('packet'),limit=data['limit'],mode='lexical')
 elif data['operation']=='read':
  result={'status':'ok','project_id':config['project']['id'],'record':load_record(data['root'],data['path'],config)}
 elif data['operation']=='records':
  result={'status':'ok','project_id':config['project']['id'],'records':load_records(data['root'],config,historical=True)}
 else:
  raise ValueError('Unsupported ontology memory operation')
 print(json.dumps(result,sort_keys=True))
except MemoryError as error:
 print(json.dumps({'status':'error','error':error.as_dict(),'results':[]}))
 sys.exit(2)
'''
    data = {"root": str(p.root), "project_id": p.project_id, "operation": operation, **arguments}
    try:
        run = subprocess.run([sys.executable, "-B", "-c", code, str(scripts)],
                             input=json.dumps(data), text=True, capture_output=True, timeout=30,
                             env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"})
    except (OSError, subprocess.TimeoutExpired) as error:
        return {"status": "unavailable", "results": [], "limitations": [f"Installed memory interface unavailable ({type(error).__name__})."]}
    try:
        value = json.loads(run.stdout)
    except ValueError:
        raise OntologyError("memory_interface_failed", "Installed memory interface did not return JSON.") from None
    if run.returncode and value.get("error"):
        error = value["error"]
        if arguments.get("packet") or error.get("code") in {"excluded_source", "unsafe_path", "project_identity", "symlink_path"}:
            raise OntologyError("memory_" + error.get("code", "error"), error.get("message", "Memory input rejected."))
        value["status"] = "unavailable"
        value["limitations"] = ["Memory retrieval rejected the input: " + error.get("code", "error")]
    elif run.returncode:
        raise OntologyError("memory_interface_failed", "Installed memory interface failed.")
    return value


def expand_query(p, query):
    query = query_text(query)
    terms = [query]
    concepts = []
    rows = ranked(p, query, kinds={"concept", "instance"})
    for _, record in rows[:3]:
        if record["lifecycle"] != "approved":
            continue
        concepts.append(record["@id"])
        terms.extend([record["label"], *record.get("aliases", [])])
        for relation in p.relations:
            if relation["subject"] == record["@id"] and relation["predicate"].rsplit(":", 1)[-1] in {"relatedTo", "broader", "narrower"}:
                related = p.by_id[relation["object"]]
                if related["lifecycle"] == "approved":
                    terms.append(related["label"])
    unique = list(dict.fromkeys(t.strip() for t in terms if t.strip()))[:8]
    return {"queries": unique, "concept_ids": sorted(set(concepts)), "max_queries": 8,
            "route": "original, resolved concepts, aliases and one-hop related vocabulary"}


def qualified_history(record):
    diagnostics = record.get("diagnostics", [])
    if not diagnostics:
        return True
    return (record.get("evidence", {}).get("historical_support") == "supported"
            and all(d.get("severity") == "info" for d in diagnostics))


def search_memory(value, query, *, limit=None, packet=None, frozen_ontology=False):
    p = project(value)
    frozen_ontology = frozen_ontology or hasattr(p, "frozen_packet")
    bound = limits(p, limit)
    expansion = expand_query(p, query)
    if frozen_ontology and packet is None:
        return {"status": "unavailable", "source_type": "historical_memory", "results": [],
                "expansion": expansion, "mutated": False,
                "limitations": ["Frozen ontology queries require an exact frozen memory packet before historical retrieval."]}
    found, limitations, excluded = {}, [], []
    mode, state = "lexical", "no_matching_historical_evidence"
    for term in expansion["queries"]:
        result = _installed(p, "search", query=term, packet=packet, limit=bound["limit"])
        limitations.extend(result.get("limitations", []))
        if result["status"] in {"unavailable", "unconfigured", "identity_mismatch"}:
            state = "unavailable"
            break
        mode = result.get("mode", "lexical")
        for row in result.get("results", []):
            # An ontology expansion never relaxes active-record/evidence policy.
            if row.get("kind") != "memory":
                continue
            if row.get("state") != "active" or not qualified_history(row):
                excluded.append({"record_id": row.get("record_id"), "reason": "inactive_or_unverified_evidence"})
                continue
            key = (row["record_id"], row["sha256"])
            if key not in found:
                found[key] = {**row, "source_type": "historical_memory", "freshness": "historical_only" if row.get("diagnostics") else "current_sources",
                              "verified_current": row.get("evidence", {}).get("verified_current", False),
                              "match_reason": "ontology_expanded_memory_" + mode, "matched_queries": [],
                              "authority": "Historical memory evidence; it does not establish current operational authority."}
            found[key]["matched_queries"].append(term)
    results = sorted(found.values(), key=lambda r: (-r["score"], r["record_id"], r["path"]))[:bound["limit"]]
    return {"status": "ok" if results else state, "mode": mode, "source_type": "historical_memory",
            "project_id": p.project_id, "results": results, "expansion": expansion, "packet": packet,
            "excluded": sorted(excluded, key=lambda r: r["record_id"] or ""),
            "limitations": sorted(set(limitations + ["Ontology requests deterministic lexical memory retrieval; backend configuration is unchanged."])), "mutated": False}


def memory_inputs(p):
    """Include exclusions and additions, not only records linked by an old build."""
    result = _installed(p, "records")
    require(result.get("status") == "ok", "memory_unavailable", "Current memory corpus cannot be inspected.")
    scripts = safe_path(p.root, ".agents/skills/memory/scripts")
    helpers = {path.name: sha256(read_bytes(safe_path(p.root, str(path.relative_to(p.root)))) )
               for path in sorted(scripts.glob("*.py"))}
    return {"configuration": sha256(read_bytes(safe_path(p.root, "memory.yaml"))), "helpers": helpers,
            "records": [{"path": r["path"], "sha256": r["sha256"],
                         "evidence_sha256": sha256(canonical_bytes(r.get("evidence"))),
                         "diagnostics_sha256": sha256(canonical_bytes(r["diagnostics"]))}
                        for r in sorted(result["records"], key=lambda item: item["path"])]}


def link_memory(value, *, record_paths=(), concept_queries=()):
    from ontology_build import write_generated
    p = project(value)
    inputs = memory_inputs(p)
    records = []
    if record_paths:
        for path in sorted(set(record_paths)):
            result = _installed(p, "read", path=path)
            if result["status"] != "ok":
                raise OntologyError("memory_unavailable", "A selected memory record is unavailable or rejected.", path=path)
            records.append(result["record"])
    else:
        result = _installed(p, "records")
        if result["status"] != "ok":
            raise OntologyError("memory_unavailable", "Accessible project memory records are unavailable.")
        records = result["records"]
    associations, exclusions, versions = [], [], []
    vocabulary = sorted({word for r in p.records if r["kind"] in {"concept", "instance"}
                         for word in [r["label"], *r.get("aliases", [])]})
    for record in records:
        meta = record["metadata"]
        if meta["state"] != "active" or not qualified_history(record):
            exclusions.append({"record_id": meta["id"], "reason": "inactive_or_unverified_evidence"})
            continue
        versions.append({"record_id": meta["id"], "path": record["path"], "sha256": record["sha256"],
                         "sources": meta["sources"]})
        content = normalize(meta["title"] + " " + record["body"])
        queries = list(concept_queries) if concept_queries else [q for q in vocabulary if re.search(r"(?<!\w)" + re.escape(normalize(q)) + r"(?!\w)", content)]
        if not queries:
            associations.append({"record_id": meta["id"], "status": "unmatched", "concept_ids": [], "query": None})
        for query in sorted(set(queries)):
            rows = ranked(p, query, kinds={"concept", "instance"})
            if rows:
                rows = [(m, r) for m, r in rows if m[:2] == rows[0][0][:2]]
            identities = sorted(r["@id"] for _, r in rows if r["lifecycle"] == "approved")
            associations.append({"record_id": meta["id"], "query": query, "concept_ids": identities,
                                 "status": "unmatched" if not identities else "ambiguous" if len(identities) > 1 else "derived_association"})
    sidecar = {"schema_version": 2, "kind": "derived-memory-concept-links", "project_id": p.project_id,
               "source_type": "derived_association", "ontology_context": p.context(),
               "memory_inputs": inputs,
               "records": sorted(versions, key=lambda r: r["record_id"]),
               "associations": associations, "excluded": exclusions,
               "authority": "Rebuildable associations; no canonical memory or ontology claim is created."}
    # Reopen exact selected records and evidence before publishing the sidecar.
    for r in sidecar["records"]:
        current = _installed(p, "read", path=r["path"])
        if current["status"] != "ok" or current["record"]["sha256"] != r["sha256"] or not qualified_history(current["record"]):
            raise OntologyError("memory_changed", "Selected memory changed during link generation.", path=r["path"])
    require(memory_inputs(p) == inputs, "memory_changed", "Memory corpus, configuration or helpers changed during link generation.")
    return write_generated(p, {".sys4ai/ontology/links/memory-records.json": canonical_bytes(sidecar)}, operation="link-memory")


def read_links(value):
    p = project(value)
    target = safe_path(p.root, ".sys4ai/ontology/links/memory-records.json", must_exist=False)
    if not target.exists():
        return {"status": "missing", "source_type": "derived_association", "results": [], "mutated": False}
    data = read_json(target)
    keys = {"schema_version", "kind", "project_id", "source_type", "ontology_context", "records", "associations", "excluded", "authority"}
    require(isinstance(data, dict) and set(data) in (keys, keys | {"memory_inputs"}), "invalid_sidecar", "Derived memory links have an unsupported shape.")
    if data.get("kind") != "derived-memory-concept-links" or data.get("project_id") != p.project_id:
        raise OntologyError("invalid_sidecar", "Derived memory links have a different project identity or kind.")
    require(data["schema_version"] in {1, 2} and isinstance(data["ontology_context"], dict)
            and isinstance(data["ontology_context"].get("snapshot_sha256"), str)
            and isinstance(data["records"], list) and isinstance(data["associations"], list)
            and isinstance(data["excluded"], list), "invalid_sidecar", "Derived memory links have incomplete versions or association lists.")
    for r in data["records"]:
        require(isinstance(r, dict) and set(r) == {"record_id", "path", "sha256", "sources"}
                and all(isinstance(r[k], str) for k in ("record_id", "path", "sha256")) and isinstance(r["sources"], list),
                "invalid_sidecar", "A derived memory record version is malformed.")
    for a in data["associations"]:
        require(isinstance(a, dict) and set(a) == {"record_id", "query", "concept_ids", "status"}
                and isinstance(a["concept_ids"], list) and all(isinstance(i, str) for i in a["concept_ids"])
                and a["status"] in {"derived_association", "ambiguous", "unmatched"}, "invalid_sidecar", "A derived association is malformed.")
    ownership_file = safe_path(p.root, ".sys4ai/ontology/manifests/link-memory.json", must_exist=False)
    ownership = read_json(ownership_file) if ownership_file.exists() else {}
    require(isinstance(ownership, dict) and isinstance(ownership.get("outputs", {}), dict), "invalid_manifest", "Memory link ownership manifest is malformed.")
    stale = data["ontology_context"]["snapshot_sha256"] != p.context()["snapshot_sha256"] or ownership.get("outputs", {}).get(".sys4ai/ontology/links/memory-records.json") != sha256(read_bytes(target))
    try:
        stale = stale or data.get("memory_inputs") != memory_inputs(p)
    except OntologyError:
        stale = True
    for r in data["records"]:
        current = _installed(p, "read", path=r["path"])
        stale = stale or current["status"] != "ok" or current.get("record", {}).get("sha256") != r["sha256"] or not qualified_history(current.get("record", {}))
    return {"status": "stale" if stale else "current", "source_type": "derived_association",
            "path": ".sys4ai/ontology/links/memory-records.json", "sha256": sha256(read_bytes(target)),
            "results": [] if stale else data["associations"], "records": data["records"], "mutated": False,
            "limitations": ["Stale associations require an explicit link-memory rebuild."] if stale else []}

"""Exact reviewed canonical publication with immutable accepted intents and receipts."""
from pathlib import Path
import copy
import re
from ontology_core import (OntologyError, load_project, canonical_bytes, sha256, safe_path, read_json,
                           read_bytes, decode_json, require, exact, digest, atomic_write, operation_lock)
from ontology_validate import validate_project
from ontology_lifecycle import validate_transition
from ontology_authority import authorize

CONTROL = "control_records/ontology/"
ONTOLOGY_GUARDED_ACTIONS = ["preview", "publish", "recover"]


def _guard(root, operation, arguments, targets):
    from ontology_guards import begin_action, require_adapter, GuardError
    try:
        decision = begin_action(root, "ontology", operation, arguments, targets)
        require_adapter(decision, __file__)
        return decision
    except GuardError as exc:
        raise OntologyError(exc.code, str(exc)) from exc


def _recheck(decision, *, targets=True):
    from ontology_guards import GuardError
    try:
        decision.recheck(targets=targets)
        if targets and decision.operation != "preview":
            decision.lock_checked = True
    except GuardError as exc:
        raise OntologyError(exc.code, str(exc)) from exc


def _root(value):
    path = Path(value).absolute()
    require(path.is_dir() and not path.is_symlink() and path == path.resolve(), "unsafe_root", "Select an existing resolved project root without symlink aliases.")
    return path


def check_proposal(root, proposal):
    exact(proposal, ("schema_version", "operation_id", "operation", "reason", "changes"))
    require(type(proposal["schema_version"]) is int and proposal["schema_version"] in {1, 2} and proposal["operation"] == "publish", "unsupported_operation", "Expected explicit versioned ontology publication.")
    require(isinstance(proposal["operation_id"], str) and re.fullmatch(r"ONTOP-[A-Za-z0-9-]{4,100}", proposal["operation_id"]), "invalid_operation", "Use a stable ONTOP operation identity.")
    require(isinstance(proposal["reason"], str) and 0 < len(proposal["reason"].strip()) <= 2000, "missing_reason", "Exact review requires a bounded reason.")
    require(isinstance(proposal["changes"], list) and 1 <= len(proposal["changes"]) <= 50, "invalid_changes", "Select one to fifty exact canonical files.")
    cfg = read_json(safe_path(root, "ontology.yaml"))
    permitted = set(cfg["project_files"] + cfg["binding_files"] + cfg.get("competency_files", []))
    if proposal["schema_version"] == 2:
        from ontology_advanced import load_advanced
        advanced = load_advanced(root, required=True)
        permitted.update(ref["path"] for ref in advanced["extensions"])
        permitted.add("ontology-advanced.yaml")
        for ref in advanced["extensions"]:
            permitted.update(s["path"] for s in read_json(safe_path(root, ref["path"])).get("shapes", []))
    seen = set()
    for change in proposal["changes"]:
        exact(change, ("path", "expected_sha256", "content", "sha256"))
        require(isinstance(change["path"], str) and change["path"] in permitted and change["path"] not in seen, "canonical_scope", "Change must select one distinct configured project canonical file.", path=change["path"] if isinstance(change["path"], str) else None)
        seen.add(change["path"]); safe_path(root, change["path"], must_exist=False)
        require(isinstance(change["content"], str) and len(change["content"].encode()) <= 250000, "invalid_content", "Provide exact reviewed UTF-8 content up to 250000 bytes.")
        digest(change["sha256"])
        if change["expected_sha256"] is not None: digest(change["expected_sha256"])
        require(sha256(change["content"].encode()) == change["sha256"], "content_digest", "Proposed content differs from its reviewed digest.")
        if not change["path"].endswith(".ttl"):
            decode_json(change["content"].encode(), path=change["path"])
    if proposal["schema_version"] == 2:
        overrides = {c["path"]: c["content"].encode() for c in proposal["changes"]}
        updated = load_advanced(root, required=True, _overrides=overrides)
        old_other = {k:v for k,v in advanced.items() if k != "extensions"}
        new_other = {k:v for k,v in updated.items() if k != "extensions"}
        require(old_other == new_other and [r["path"] for r in advanced["extensions"]] == [r["path"] for r in updated["extensions"]],
                "advanced_config_scope", "Semantic publication may update existing extension locks only; profiles, authority, limits and new imports use selected setup.")
        for ref in advanced["extensions"]:
            if ref["path"] in overrides:
                before = read_json(safe_path(root, ref["path"]))
                after = decode_json(overrides[ref["path"]])
                require(before["id"] == after.get("id") and before["project_id"] == after.get("project_id"), "identity_recycled", "An extension retains its stable identity and project.")
                for key in ("axioms", "annotations", "negative_assertions"):
                    old_statements = {r["id"]: r for r in before[key]}
                    new_statements = {r["id"]: r for r in after.get(key, [])}
                    require(all(new_statements.get(rid) == record for rid,record in old_statements.items()),
                            "extension_history", "Published extension statement identities and their meaning are immutable; add distinct sourced statements through review.")
                require(before.get("shapes", []) == after.get("shapes", []) or
                        [s["path"] for s in before.get("shapes", [])] == [s["path"] for s in after.get("shapes", [])],
                        "advanced_config_scope", "New shape selection requires selected setup.")
    return proposal


def _candidate(root, proposal, *, old_overrides=None):
    prior_all = dict(old_overrides or {})
    config = read_json(safe_path(root, "ontology.yaml"))
    core_paths = set(config["project_files"] + config["binding_files"] + config.get("competency_files", []))
    prior = {p:b for p,b in prior_all.items() if p in core_paths}
    for change in proposal["changes"]:
        if change["expected_sha256"] is None and change["path"] in core_paths:
            empty = {"schema_version": 1, "questions": []} if change["path"] in config.get("competency_files", []) else {"@context": config["context"]["path"], "@graph": []}
            prior[change["path"]] = canonical_bytes(empty)
    old = load_project(root, validate=False, _overrides=prior)
    for change in proposal["changes"]:
        if change["expected_sha256"] is None: old.snapshot["inputs"][change["path"]] = None
    overrides = {c["path"]: c["content"].encode() for c in proposal["changes"]}
    new = load_project(root, _overrides={p:b for p,b in overrides.items() if p in core_paths})
    if proposal["schema_version"] == 2:
        from ontology_advanced import load_advanced, load_extensions
        for project, selected in ((old, prior_all), (new, overrides)):
            advanced = load_advanced(root, required=True, _overrides=selected)
            extensions, inputs, sources = load_extensions(project, advanced, _overrides=selected)
            require(all(s["status"] == "current" for s in sources), "source_not_current", "Extensions must cite current selected source bytes.")
            inputs["ontology-advanced.yaml"] = sha256(selected.get("ontology-advanced.yaml", read_bytes(safe_path(root, "ontology-advanced.yaml"))))
            project.snapshot["inputs"].update(inputs)
            project.snapshot["advanced"] = {"config": advanced, "extensions": extensions}
    require(all(s["status"] == "current" for s in new.sources), "source_not_current", "Proposed complete graph must cite current selected sources.")
    findings = validate_transition(old.records, new.records)
    require(not findings, findings[0]["code"] if findings else "invalid_transition", findings[0]["message"] if findings else "", record_id=findings[0]["record_id"] if findings else None)
    return old, new


def _advanced_checks(root, proposal):
    if proposal["schema_version"] != 2:
        return None
    from ontology_advanced import load_advanced
    from ontology_standards import validate, infer, health
    cfg = load_advanced(root, required=True)
    require(cfg["profiles"].get("standards", {}).get("enabled"), "standards_required", "Advanced publication requires selected standards validation.")
    overrides = {c["path"]: c["content"].encode() for c in proposal["changes"]}
    checked = validate(root, overrides=overrides)
    require(checked.get("complete") is True and checked.get("conforms") is True,
            "advanced_validation_failed", "The exact advanced candidate did not complete conformant standards validation: " + str(checked.get("status")))
    if cfg["profiles"].get("inference", {}).get("enabled"):
        inferred = infer(root, overrides=overrides)
        require(inferred.get("complete") is True and inferred.get("status") == "ok" and inferred.get("trusted") is True,
                "advanced_consistency_failed", "The exact advanced candidate did not establish consistent finite reasoning: " + str(inferred.get("status")))
    return {"standards": "conformant", "inference": "consistent" if cfg["profiles"].get("inference", {}).get("enabled") else "not_applicable",
            "context": checked.get("context"), "versions": checked.get("versions"), "readiness": health(root)}


def preview(root, proposal):
    root = _root(root)
    check_proposal(root, proposal)
    decision = _guard(root, "preview", {"proposal": proposal}, [c["path"] for c in proposal["changes"]])
    for change in proposal["changes"]:
        path = safe_path(root, change["path"], must_exist=False)
        require((sha256(path) if path.exists() else None) == change["expected_sha256"], "expected_changed", "Canonical bytes changed since the proposed review.", path=change["path"])
    old, new = _candidate(root, proposal)
    advanced_validation = _advanced_checks(root, proposal)
    value = {"schema_version": 1, "operation_id": proposal["operation_id"], "payload_sha256": sha256(canonical_bytes(proposal)), "reason": proposal["reason"], "changes": [{k: c[k] for k in ("path", "expected_sha256", "sha256")} for c in proposal["changes"]], "before": old.context(), "after": new.context(), "valid": True}
    if advanced_validation is not None:
        value["advanced_validation"] = advanced_validation
    _recheck(decision)
    value = decision.finish(value)
    value["preview_sha256"] = sha256(canonical_bytes(value))
    return value


def _intent_paths(operation_id):
    require(isinstance(operation_id, str) and re.fullmatch(r"ONTOP-[A-Za-z0-9-]{4,100}", operation_id), "invalid_operation", "Expected exact ONTOP operation identity.")
    return tuple(CONTROL + kind + "/" + operation_id + ".json" for kind in ("intents", "receipts", "recovery"))


def _read_intent(root, operation_id):
    path, _, _ = _intent_paths(operation_id)
    intent = read_json(safe_path(root, path))
    exact(intent, ("schema_version", "proposal", "preview", "prior_contents", "publisher", "intent_sha256"))
    checked = dict(intent); checked.pop("intent_sha256")
    require(sha256(canonical_bytes(checked)) == intent["intent_sha256"], "intent_changed", "Accepted intent integrity differs.")
    require(intent["proposal"]["operation_id"] == operation_id, "intent_changed", "Accepted intent operation identity differs.")
    check_proposal(root, intent["proposal"])
    require(intent["preview"]["payload_sha256"] == sha256(canonical_bytes(intent["proposal"])), "intent_changed", "Accepted intent payload differs from its reviewed preview.")
    reviewed = dict(intent["preview"]); reviewed.pop("preview_sha256", None)
    require(sha256(canonical_bytes(reviewed)) == intent["preview"].get("preview_sha256"), "intent_changed", "Accepted preview no longer matches the reviewed digest.")
    for change in intent["proposal"]["changes"]:
        content = intent["prior_contents"].get(change["path"])
        require((sha256(content.encode()) if isinstance(content, str) else None) == change["expected_sha256"], "intent_changed", "Accepted prior content differs from the reviewed expected version.")
    return intent


def _advance(root, intent, grant, *, fail_at=None, decision=None):
    proposal, pre = intent["proposal"], intent["preview"]
    journal_path, receipt_path, recovery_path = _intent_paths(proposal["operation_id"])
    old, new = _candidate(root, proposal, old_overrides={p: value.encode() for p, value in intent["prior_contents"].items() if value is not None})
    advanced_validation = _advanced_checks(root, proposal)
    require(advanced_validation == pre.get("advanced_validation"), "advanced_context_changed", "Advanced rules, shapes, helpers or certified runtime changed after accepted review.")
    if decision is not None:
        _recheck(decision)
    authorize(old, grant, proposal, pre["preview_sha256"])
    changed = {c["path"] for c in proposal["changes"]}
    for relative, expected in pre["before"]["inputs"].items():
        if relative in changed: continue
        file = safe_path(root, relative, must_exist=False)
        require((sha256(file) if file.exists() else None) == expected, "recovery_input_changed", "Accepted source/configuration/module input changed.", path=relative)
    require(old.context()["helpers"] == pre["before"]["helpers"], "helper_changed", "Helper version changed after accepted review.")
    states = []
    for c in proposal["changes"]:
        path = safe_path(root, c["path"], must_exist=False)
        actual = sha256(path) if path.exists() else None
        require(actual in {c["expected_sha256"], c["sha256"]}, "recovery_conflict", "Canonical file contains unrelated edits; preserve them.", path=c["path"])
        states.append({"path": c["path"], "before_sha256": c["expected_sha256"], "sha256": c["sha256"], "state": "committed" if actual == c["sha256"] else "pending"})
    existing_receipt = safe_path(root, receipt_path, must_exist=False)
    if existing_receipt.exists():
        receipt = read_json(existing_receipt)
        require(receipt.get("intent_sha256") == intent["intent_sha256"] and all(s["state"] == "committed" for s in states), "receipt_conflict", "Completed receipt no longer agrees with actual canonical files.")
        from ontology_health import maintenance_status
        return {**receipt, "current_readiness": maintenance_status(root)}
    try:
        if fail_at == "before_commit": raise OSError("Injected pre-commit failure")
        for index, (change, state) in enumerate(zip(proposal["changes"], states)):
            if state["state"] != "committed":
                if decision is not None:
                    _recheck(decision, targets=False)
                atomic_write(root, change["path"], change["content"].encode(), change["expected_sha256"])
                state["state"] = "committed"
            if fail_at == "after_commit" or fail_at == f"after_commit:{index+1}": raise OSError("Injected post-commit failure")
        if fail_at == "projection": raise OSError("Injected projection failure")
        from ontology_build import compile_project
        projection = compile_project(root)
        receipt = {"schema_version": 1, "status": "complete", "operation_id": proposal["operation_id"], "payload_sha256": pre["payload_sha256"], "preview_sha256": pre["preview_sha256"], "intent_sha256": intent["intent_sha256"], "reason": proposal["reason"], "publisher": intent["publisher"], "files": states, "projection": projection, "context": load_project(root).context()}
        if fail_at == "receipt": raise OSError("Injected receipt failure")
        atomic_write(root, receipt_path, canonical_bytes(receipt), None)
        from ontology_health import maintenance_status
        return {**receipt, "current_readiness": maintenance_status(root)}
    except (OSError, OntologyError) as exc:
        recovery = {"schema_version": 1, "status": "partial", "operation_id": proposal["operation_id"], "intent_sha256": intent["intent_sha256"], "files": states, "error": {"code": getattr(exc, "code", "write_failure"), "message": str(exc)[:1000]}, "recovery": "Renew the current grant for the original payload/preview and recover this exact operation."}
        path = safe_path(root, recovery_path, must_exist=False)
        atomic_write(root, recovery_path, canonical_bytes(recovery), sha256(path) if path.exists() else None)
        return recovery


def publish(root, proposal, grant, *, expected_preview_sha256, fail_at=None):
    root = _root(root)
    check_proposal(root, proposal)
    decision = _guard(root, "publish", {"proposal": proposal, "grant": grant, "expected_preview_sha256": expected_preview_sha256}, [c["path"] for c in proposal["changes"]])
    journal_path, _, _ = _intent_paths(proposal["operation_id"])
    journal_file = safe_path(root, journal_path, must_exist=False)
    if journal_file.exists():
        intent = _read_intent(root, proposal["operation_id"])
        require(intent["proposal"] == proposal and intent["preview"]["preview_sha256"] == expected_preview_sha256, "operation_reused", "Operation identity cannot be reused for a different accepted change.")
        with operation_lock(root, CONTROL + "publication.lock"):
            return decision.finish(_advance(root, intent, grant, fail_at=fail_at, decision=decision))
    pre = preview(root, proposal)
    require(pre["preview_sha256"] == expected_preview_sha256, "preview_changed", "Exact reviewed preview differs from current proposed state.")
    project, _ = _candidate(root, proposal)
    authorize(project, grant, proposal, expected_preview_sha256)
    with operation_lock(root, CONTROL + "publication.lock"):
        _recheck(decision)
        require(not journal_file.exists(), "operation_race", "Another writer accepted this operation; retry its exact recorded payload.")
        pre = preview(root, proposal)
        require(pre["preview_sha256"] == expected_preview_sha256, "preview_changed", "Inputs changed while acquiring publication lock.")
        authorize(project, grant, proposal, expected_preview_sha256)
        intent = {"schema_version": 1, "proposal": copy.deepcopy(proposal), "preview": pre, "prior_contents": {c["path"]: read_bytes(safe_path(root, c["path"])).decode() if c["expected_sha256"] is not None else None for c in proposal["changes"]}, "publisher": {"actor_id": grant["actor_id"], "actor_kind": grant["actor_kind"], "grant_id": grant["grant_id"], "grant_sha256": sha256(canonical_bytes(grant)), "task": grant["task"]}}
        intent["intent_sha256"] = sha256(canonical_bytes(intent))
        require(len(canonical_bytes(intent)) <= 2_000_000, "intent_too_large", "Accepted operation exceeds bounded durable intent size.")
        if fail_at == "before_intent": raise OntologyError("injected_failure", "Injected failure before accepted intent.")
        atomic_write(root, journal_path, canonical_bytes(intent), None)
        return decision.finish(_advance(root, intent, grant, fail_at=fail_at, decision=decision))


def recover(root, operation_id, grant, *, fail_at=None):
    root = _root(root)
    intent = _read_intent(root, operation_id)
    decision = _guard(root, "recover", {"intent": intent, "grant": grant, "operation_id": operation_id}, [c["path"] for c in intent["proposal"]["changes"]])
    with operation_lock(root, CONTROL + "publication.lock"):
        require(_read_intent(root, operation_id) == intent, "intent_changed", "Accepted intent changed while acquiring recovery lock.")
        return decision.finish(_advance(root, intent, grant, fail_at=fail_at, decision=decision))

"""Explicit compact-v1 to RDF mapping. Never parse the compact context as OWL."""
from ontology_core import CORE, canonical_bytes, sha256
from ontology_advanced import RDF, RDFS, OWL, term

FIELD = CORE + "field:"
ADV = "urn:sys4ai:ontology:advanced:"
PROV = "http://www.w3.org/ns/prov#"


def node(value):
    from rdflib import URIRef, Literal, BNode
    term(value, blank=True)
    if isinstance(value, str): return URIRef(value)
    if 'bnode' in value: return BNode(value['bnode'])
    return Literal(value['value'], datatype=URIRef(value['datatype']) if 'datatype' in value else None,
                   lang=value.get('language'), normalize=False)


def encode(value):
    from rdflib import URIRef, Literal, BNode
    if isinstance(value, URIRef): return str(value)
    if isinstance(value, BNode): return {'bnode': str(value)}
    if isinstance(value, Literal):
        result = {'value': str(value)}
        if value.language: result['language'] = value.language.lower()
        elif value.datatype: result['datatype'] = str(value.datatype)
        return result
    raise ValueError('Unsupported RDF term')


def graph_ids(project_id):
    return {kind: 'urn:sys4ai:ontology:graph:' + project_id + ':' + kind for kind in ('asserted', 'derived', 'inferred', 'external')}


def normalized_triples(graph):
    from rdflib.compare import to_canonical_graph
    rows = [[encode(v) for v in triple] for triple in to_canonical_graph(graph)]
    return sorted(rows, key=canonical_bytes)


def quad_rows(dataset):
    # Canonicalize a reified quad graph once, retaining bnode identity across graphs.
    from rdflib import Graph, BNode, URIRef
    from rdflib.compare import to_canonical_graph
    # Ground RDF terms already have stable identities; introducing quad bnodes
    # makes canonicalization expensive without changing their encoded values.
    if not any(isinstance(value,BNode) for quad in dataset.quads((None,None,None,None)) for value in quad):
        return sorted([[encode(value) for value in quad] for quad in dataset.quads((None,None,None,None))],key=canonical_bytes)
    q = Graph()
    keys = [URIRef(ADV+k) for k in ('s','p','o','g')]
    for index, (s,p,o,g) in enumerate(dataset.quads((None,None,None,None))):
        n=BNode('quad'+str(index))
        for key,value in zip(keys, (s,p,o,g)): q.add((n,key,value))
    q=to_canonical_graph(q)
    rows=[]
    for n in q.subjects(keys[0], None):
        rows.append([encode(q.value(n,key)) for key in keys])
    return sorted(rows,key=canonical_bytes)


def from_quads(rows):
    from rdflib import Dataset
    ds=Dataset(default_union=False)
    for s,p,o,g in rows: ds.graph(node(g)).add((node(s),node(p),node(o)))
    return ds


def project_dataset(payload):
    from rdflib import Dataset, URIRef, Literal
    ds = Dataset(default_union=False)
    names=graph_ids(payload['context']['project_id'])
    graphs={name: ds.graph(URIRef(iri)) for name,iri in names.items()}
    provenance=graphs['derived']; premises=[]
    sources={canonical_bytes({k:s[k] for k in ('path','sha256','locator')}):s for s in payload['sources']}
    for record in payload['records']:
        subject=URIRef(record['@id']); kind=record.get('fact_kind','asserted')
        graph=graphs[kind]
        current=all(sources.get(canonical_bytes(s),{}).get('status')=='current' for s in record.get('sources',[]))
        approved=record.get('lifecycle')=='approved' and kind=='asserted' and current and bool(record.get('sources'))
        semantic=[]
        for typ in record.get('@type',[]): semantic.append((subject,URIRef(RDF+'type'),URIRef(typ)))
        if record['kind']=='concept': graph.add((subject,URIRef(RDF+'type'),URIRef(RDFS+'Class')))
        if record['kind']=='predicate': graph.add((subject,URIRef(RDF+'type'),URIRef(RDF+'Property')))
        if record['kind']=='relation':
            predicate=RDFS+'subClassOf' if record.get('predicate')==CORE+'subtypeOf' else record.get('predicate')
            if record.get('subject') and predicate and record.get('object'):
                semantic.append((URIRef(record['subject']),URIRef(predicate),URIRef(record['object'])))
        for triple in semantic:
            graph.add(triple)
            if approved:
                premises.append({'id':record['@id']+':'+sha256(canonical_bytes([encode(x) for x in triple]))[:16],
                    'triple':[encode(x) for x in triple], 'record_id':record['@id'], 'sources':record['sources'], 'approved':True})
        for key,value in record.items():
            if key.startswith('@') or key=='sources': continue
            if isinstance(value,str):
                graph.add((subject,URIRef(FIELD+key),URIRef(value) if key in {'subject','predicate','object','entity','replacement'} else Literal(value)))
            elif isinstance(value,list):
                for entry in value:
                    if isinstance(entry,str): graph.add((subject,URIRef(FIELD+key),URIRef(entry) if key in {'domain','range','ambiguity_with'} else Literal(entry)))
                    else: graph.add((subject,URIRef(FIELD+key),Literal(canonical_bytes(entry).decode(),datatype=URIRef(RDF+'JSON'),normalize=False)))
            elif isinstance(value,dict): graph.add((subject,URIRef(FIELD+key),Literal(canonical_bytes(value).decode(),datatype=URIRef(RDF+'JSON'),normalize=False)))
            elif isinstance(value,(bool,int,float)): graph.add((subject,URIRef(FIELD+key),Literal(value)))
        if record.get('lifecycle') in {'approved','deprecated'}:
            provenance.add((subject,URIRef(RDF+'type'),URIRef(ADV+'ApprovedRecord')))
        from ontology_provenance import add_sources
        add_sources(provenance,subject,record.get('sources',[]),sources,payload['context'])
    for extension in payload.get('extensions',[]):
        for field in ('axioms','annotations'):
            for statement in extension[field]:
                triple=tuple(node(statement[k]) for k in ('subject','predicate','object'))
                graphs['asserted'].add(triple)
                if field=='axioms' and all(sources.get(canonical_bytes(s),{}).get('status')=='current' for s in statement['sources']):
                    premises.append({'id':statement['id'],'triple':[encode(x) for x in triple], 'record_id':statement['id'], 'sources':statement['sources'], 'approved':True})
                from ontology_provenance import add_sources
                add_sources(provenance,URIRef(statement['id']),statement['sources'],sources,payload['context'])
        for statement in extension['negative_assertions']:
            identifier=URIRef(statement['id']); graph=graphs['asserted']
            graph.add((identifier,URIRef(RDF+'type'),URIRef(OWL+'NegativePropertyAssertion')))
            graph.add((identifier,URIRef(OWL+'sourceIndividual'),node(statement['subject'])))
            graph.add((identifier,URIRef(OWL+'assertionProperty'),node(statement['predicate'])))
            target='targetIndividual' if isinstance(statement['object'],str) else 'targetValue'
            graph.add((identifier,URIRef(OWL+target),node(statement['object'])))
            from ontology_provenance import add_sources
            add_sources(provenance,identifier,statement['sources'],sources,payload['context'])
    return ds, names, sorted(premises,key=lambda p:p['id'])

"""Deterministic vocabulary retrieval from canonical or explicitly frozen inputs."""
import copy
import re

from ontology_core import OntologyError, canonical_bytes, load_project, source_status


def project(value):
    return value if hasattr(value, "by_id") else load_project(value)


def limits(p, limit=None, max_bytes=None, hops=None):
    settings = p.config["retrieval"]
    result = {"limit": settings["default_limit"] if limit is None else limit,
              "max_bytes": settings["max_context_bytes"] if max_bytes is None else max_bytes,
              "hops": settings["default_hops"] if hops is None else hops}
    for key, low, high in (("limit", 1, min(100, settings["max_limit"])),
                           ("hops", 0, min(8, settings["max_hops"])),
                           ("max_bytes", 1024, min(32000, settings["max_context_bytes"]))):
        if type(result[key]) is not int or not low <= result[key] <= high:
            raise OntologyError("invalid_limit", f"{key} must be between {low} and {high}.")
    return result


def normalize(value):
    return " ".join(value.casefold().split())


def tokens(value):
    return set(re.findall(r"[\w]+", re.sub(r"(?<=[a-z])(?=[A-Z])", " ", value).casefold()))


def query_text(query):
    if not isinstance(query, str) or not query.strip() or len(query) > 4096:
        raise OntologyError("invalid_query", "Supply a nonempty query of at most 4096 characters.")
    return query.strip()


def match(record, query):
    q = normalize(query)
    if record["@id"] == query:
        return 0, 1, "stable_id"
    if normalize(record["label"]) == q:
        return 1, 1, "preferred_label"
    if q in [normalize(a) for a in record.get("aliases", [])]:
        return 2, 1, "alias"
    words = tokens(query)
    vocabulary = record["label"] + " " + " ".join(record.get("aliases", []))
    text = vocabulary + " " + record["definition"] + " " + record.get("scope_note", "")
    overlap = len(words & tokens(text))
    score = overlap * 10 + len(words & tokens(vocabulary)) * 5 + (20 if q in normalize(text) else 0)
    return (3, score, "lexical") if overlap else None


def ranked(p, query, *, kinds=None):
    query = query_text(query)
    results = []
    for record in p.records:
        if kinds is not None and record["kind"] not in kinds:
            continue
        reason = match(record, query)
        if reason:
            results.append((reason, record))
    results.sort(key=lambda item: (item[0][0], -item[0][1], item[1]["@id"]))
    return results


def explain(p, record, reason="selected", score=None):
    result = copy.deepcopy(record)
    result.update(source_type="ontology", match_reason=reason,
                  canonical_location=p.locations.get(record["@id"]),
                  module_version=next((m.get("version") for m in p.modules if m.get("id", m.get("module_id")) == record["module"]), None))
    bindings = [b for b in p.records if b["kind"] == "binding" and b["entity"] == record["@id"]]
    result["bindings"] = copy.deepcopy(bindings)
    sources = {canonical_bytes(s): s for b in [record, *bindings] for s in b.get("sources", [])}
    result["source_status"] = [source_status(p, sources[key]) for key in sorted(sources)]
    states = {s["status"] for s in result["source_status"]}
    result["freshness"] = "unavailable" if "unavailable" in states else "stale" if "stale" in states else "current"
    if score is not None:
        result["match_score"] = score
    result["relationships"] = [copy.deepcopy(r) for r in p.relations
                               if record["@id"] in (r["subject"], r["object"])]
    return result


def envelope(p, operation, query, results, bound, *, status="ok", truncated=False, **extra):
    context = p.context()
    # The full snapshot is reproducible by its digest; return exact versions for
    # the selected records rather than duplicating every unrelated source.
    compact = {k: copy.deepcopy(v) for k, v in context.items()
               if k in {"project_id", "profile_version", "generator_version", "snapshot_sha256", "config_sha256", "modules", "configuration"}}
    compact["config_sha256"] = context.get("inputs", {}).get("ontology.yaml")
    result = {"operation": operation, "query": query, "project_id": p.project_id,
              "status": status, "results": results[:bound["limit"]],
              "context": compact, "diagnostics": copy.deepcopy(p.diagnostics),
              "limits": bound, "truncation": {"truncated": truncated or len(results) > bound["limit"],
                 "available_results": len(results), "returned_results": min(len(results), bound["limit"])},
              "mutated": False,
              "authority": "Semantic source data; current user, project, role, skill and Task authority control action.", **extra}
    while len(canonical_bytes(result)) + 256 > bound["max_bytes"] and result["results"]:
        result["results"].pop()
        result["truncation"]["truncated"] = True
    if len(canonical_bytes(result)) + 256 > bound["max_bytes"]:
        result["diagnostics"] = [{"code": "diagnostics_truncated", "message": "Run health to inspect complete diagnostics."}]
        result["context"] = {k: v for k, v in compact.items() if k in {"project_id", "snapshot_sha256", "config_sha256"}}
        result["truncation"]["truncated"] = True
    if len(canonical_bytes(result)) > bound["max_bytes"]:
        raise OntologyError("context_too_large", "Response metadata exceeds the requested byte bound; use a larger bound.")
    result["truncation"]["returned_results"] = len(result["results"])
    return result


def search(value, query, *, limit=None, max_bytes=None, kinds=None, semantic=True):
    p = project(value)
    bound = limits(p, limit, max_bytes)
    rows = ranked(p, query, kinds=kinds or {"concept", "instance", "predicate"})
    results = [explain(p, r, m[2], m[1]) for m, r in rows]
    if semantic and getattr(p, "frozen_packet", {}).get("schema_version") == 2:
        from ontology_advanced_packet import frozen_search
        frozen = frozen_search(p, query, limit=limit, max_bytes=max_bytes)
        if frozen is not None:
            return frozen
    if semantic and not hasattr(p, "frozen_packet") and (not rows or rows[0][0][0] == 3):
        from ontology_semantic import profile, search as semantic_search
        try:
            cfg, _ = profile(p.root)
            if cfg["enabled"]:
                return semantic_search(p, query, limit=limit, max_bytes=max_bytes, kinds=kinds)
        except OntologyError as error:
            return envelope(p, "search", query, results, bound, status="ok" if rows else "no_match",
                            semantic={"status": "unavailable", "used": False, "diagnostic": error.as_dict()})
    return envelope(p, "search", query, results, bound, status="ok" if rows else "no_match")


def term(value, query, *, limit=None, max_bytes=None):
    p = project(value)
    bound = limits(p, limit, max_bytes)
    rows = ranked(p, query, kinds={"concept", "instance", "predicate"})
    if rows:
        best = rows[0][0][:2]
        rows = [(m, r) for m, r in rows if m[:2] == best]
    if not rows or rows[0][0][0] == 3:
        result = search(p, query, limit=limit, max_bytes=max_bytes)
        if result.get("semantic", {}).get("used"):
            result["operation"] = "term"
            result["status"] = "semantic_candidates" if result["results"] else "no_match"
            return result
    results = [explain(p, r, m[2], m[1]) for m, r in rows]
    return envelope(p, "term", query, results, bound,
                    status="ambiguous" if len(rows) > 1 else "ok" if rows else "no_match")


def read(value, identifier, *, max_bytes=None):
    p = project(value)
    query_text(identifier)
    rows = [explain(p, p.by_id[identifier], "stable_id")] if identifier in p.by_id else []
    return envelope(p, "read", identifier, rows, limits(p, 1, max_bytes), status="ok" if rows else "no_match")


def resolve_one(p, query):
    rows = ranked(p, query, kinds={"concept", "instance", "predicate"})
    if not rows:
        raise OntologyError("no_match", f"No ontology match for {query!r}.")
    best = [r for m, r in rows if m[:2] == rows[0][0][:2]]
    if len(best) != 1:
        raise OntologyError("ambiguous_term", "Ambiguous vocabulary; use a stable ID: " + ", ".join(r["@id"] for r in best))
    return best[0]


def human(result):
    lines = [f"{result.get('project_id', 'unresolved')}: {result.get('operation', 'ontology')} ({result.get('status', 'checked')})"]
    if result.get("assessment"):
        selected = result["assessment"]
        lines.append("Project root: " + selected["project_root"])
        lines.append(f"Assessment: {selected['scope']} / {selected['level']} at {selected['observed_at']}")
        for name, component in selected["components"].items():
            if component.get("required"):
                lines.append(f"  {name}: {'ready' if component.get('ready') else 'not ready'} ({component.get('status', 'canonical integrity')})")
        for name, detail in result.get("profiles", {}).items():
            lines.append(f"  {name}: {detail.get('status')}" + (f"; service {detail['service_state']}" if "service_state" in detail else ""))
    for r in result.get("results", []):
        lines.append(f"{r.get('label', r.get('record_id', r.get('path', 'evidence')))} [{r.get('@id', r.get('record_id', r.get('path', '')))}] "
                     f"({r.get('lifecycle', r.get('source_type', 'evidence'))}; {r.get('match_reason', 'selected')}; {r.get('freshness', 'see source')})")
        lines.append(r.get("definition", r.get("excerpt", "")))
        if r.get("scope_note"):
            lines.append(r["scope_note"])
        for s in r.get("source_status", r.get("sources", [])):
            lines.append(f"  Source: {s['path']} [{s['sha256']}] {s.get('locator', '')} ({s.get('status', 'recorded')})")
        for edge in r.get("relationships", []):
            lines.append(f"  {edge['subject']} --{edge['predicate']}--> {edge['object']} [{edge['fact_kind']}]")
        if r.get("kind") == "relation":
            lines.append(f"  {r['subject']} --{r['predicate']}--> {r['object']} [{r['fact_kind']}; {r.get('direction', 'canonical direction')}]")
        if r.get("sha256") and r.get("path"):
            lines.append(f"  Source: {r['path']} [{r['sha256']}] {r.get('locator', '')}")
        if r.get("discrepancy"):
            lines.append(f"  Discrepancy: {r['discrepancy']}; recorded source SHA256 {r.get('recorded_sha256')}")
        if r.get("replacement"):
            lines.append(f"  Replacement: {r['replacement']}; {r.get('deprecation_reason', '')}")
    if result.get("truncation", {}).get("truncated"):
        lines.append("Results were truncated at the declared bounds.")
    if result.get("memory"):
        lines.append("Historical evidence: " + result["memory"]["status"] + " (" + result["memory"].get("mode", "unavailable") + ")")
        lines.extend(result["memory"].get("limitations", []))
    if result.get("context", {}).get("snapshot_sha256"):
        lines.append("Input snapshot: " + result["context"]["snapshot_sha256"])
    if result.get("generated"):
        lines.extend(operation + ": " + value["status"] for operation, value in result["generated"].items())
    if result.get("structural"):
        lines.append("Structural validation: " + ("passed" if result["structural"]["valid"] else "failed"))
        lines.append("Competency validation: " + ("passed" if result["competency"]["valid"] else "failed"))
    return "\n".join(lines)

"""Real pySHACL core constraint validation with closed feature selection."""
from ontology_core import OntologyError, canonical_bytes, require

SH='http://www.w3.org/ns/shacl#'
ALLOWED={'NodeShape','PropertyShape','targetNode','targetClass','targetSubjectsOf','targetObjectsOf',
    'property','path','minCount','maxCount','minLength','maxLength','datatype','class','nodeKind',
    'IRI','BlankNode','Literal','BlankNodeOrIRI','IRIOrLiteral','BlankNodeOrLiteral','in','hasValue',
    'node','or','and','not','xone','closed','ignoredProperties','pattern','flags','message','severity',
    'Violation','Warning','Info','name','description','order','deactivated','qualifiedValueShape',
    'qualifiedMinCount','qualifiedMaxCount','qualifiedValueShapesDisjoint','equals','disjoint',
    'lessThan','lessThanOrEquals','minInclusive','maxInclusive','minExclusive','maxExclusive',
    'languageIn','uniqueLang','alternativePath','inversePath','zeroOrMorePath','oneOrMorePath','zeroOrOnePath'}


def shapes_for_records(records):
    """Build every target, sharing only equal immutable constraint subgraphs."""
    from rdflib import Graph, URIRef, Literal, BNode
    from rdflib.collection import Collection
    from ontology_rdf import FIELD, PROV, ADV
    from ontology_advanced import RDF, CORE
    graph=Graph(); u=lambda v:URIRef(SH+v)
    # Per-call caches never retain shapes across input or package revisions.
    lists={}; properties={}
    by_id={r['@id']:r for r in records}; parents={}
    for r in records:
        if r.get('predicate')==CORE+'subtypeOf': parents.setdefault(r.get('subject'),set()).add(r.get('object'))
    def types(r):
        found=set(r.get('@type',[]))|({r['@id']} if r['kind']=='concept' else set()); todo=list(found)
        while todo:
            for t in parents.get(todo.pop(),()):
                if t not in found: found.add(t); todo.append(t)
        return found
    def prop(shape,path,**values):
        constraints=tuple(sorted((key,value if isinstance(value,(URIRef,BNode)) else Literal(value)) for key,value in values.items()))
        key=(path,constraints)
        if key not in properties:
            p=properties[key]=BNode(); graph.add((p,u('path'),URIRef(path)))
            for name,value in constraints: graph.add((p,u(name),value))
        graph.add((shape,u('property'),properties[key]))
    for r in records:
        rid=URIRef(r['@id']); shape=URIRef(ADV+'shape:'+r['@id']); graph.add((shape,URIRef(RDF+'type'),u('NodeShape'))); graph.add((shape,u('targetNode'),rid))
        if r.get('lifecycle') in {'approved','deprecated'}:
            for field in ('definition','label','module'):
                prop(shape,FIELD+field,minCount=1,minLength=1)
            prop(shape,PROV+'wasDerivedFrom',minCount=1,nodeKind=u('IRI'))
        for field in ('subject','predicate','object','entity'):
            if field in r:
                selected=list(by_id)
                if r['kind']=='relation' and r.get('predicate') in by_id:
                    predicate=by_id[r['predicate']]
                    if field in ('subject','object'):
                        eligible=set(predicate.get('domain' if field=='subject' else 'range',[]))
                        selected=[v['@id'] for v in records if types(v)&eligible]
                    elif field=='predicate': selected=[v['@id'] for v in records if v['kind']=='predicate']
                # Equal immutable value lists may share RDF cells. Keep this
                # cache local to this graph so changed inputs are always rebuilt.
                values=tuple(sorted(selected))
                if values not in lists:
                    lists[values]=BNode()
                    Collection(graph,lists[values],[URIRef(x) for x in values])
                prop(shape,FIELD+field,minCount=1,maxCount=1,nodeKind=u('IRI'),**{'in':lists[values]})
        for predicate in (v for v in records if v['kind']=='predicate'):
            cardinality=predicate.get('cardinality',{})
            if types(r)&set(predicate.get('domain',[])):
                values={'minCount':cardinality.get('min',0)}
                if cardinality.get('max') is not None: values['maxCount']=cardinality['max']
                prop(shape,predicate['@id'],**values)
    return graph


def validate(dataset,names,selected,records,shape_texts,bound,custom_triples=None):
    from rdflib import Graph, URIRef
    from ontology_rdf import node,encode
    from ontology_interchange import parse
    from ontology_advanced import RDF, OWL
    import pyshacl
    from pyshacl.errors import ValidationFailure
    require(not any(k in {'inferred',names['inferred']} for k in selected),'invalid_graph_scope','SHACL authoring validation cannot use inferred evidence.')
    data=Graph()
    if custom_triples is not None:
        for triple in custom_triples:
            require(isinstance(triple,list) and len(triple)==3,'invalid_input','Validation triples require three RDF terms.')
            data.add(tuple(node(x) for x in triple))
        shapes=Graph()
    else:
        for kind in selected:
            for triple in dataset.graph(URIRef(names.get(kind,kind))): data.add(triple)
        shapes=shapes_for_records(records)
    for text in shape_texts:
        parsed=parse(text,'turtle',graph_id='urn:sys4ai:ontology:shapes',bound=bound)
        for s,p,o,g in parsed.quads((None,None,None,None)): shapes.add((s,p,o))
    for s,p,o in shapes:
        for value in (p,o):
            if str(value).startswith(SH): require(str(value)[len(SH):] in ALLOWED,'unsupported_feature','SHACL feature is outside the selected non-executable profile: '+str(value))
        require(str(p)!=OWL+'imports','unsupported_feature','Shape imports are forbidden.')
    try:
        conforms,report,_=pyshacl.validate(data,shacl_graph=shapes,inference='none',advanced=False,js=False,
            do_owl_imports=False,meta_shacl=True,inplace=False,abort_on_first=False,allow_infos=False,allow_warnings=False,max_validation_depth=32)
    except Exception as exc:
        return {'status':'processing_failure','complete':False,'diagnostics':[{'code':type(exc).__name__,'message':str(exc)[:1000]}],'inference':'none','graph_scope':selected}
    if isinstance(report,ValidationFailure):
        return {'status':'processing_failure','complete':False,'diagnostics':[{'code':'ValidationFailure','message':str(report)[:1000]}],'inference':'none','graph_scope':selected}
    findings=[]
    for result in report.subjects(URIRef(RDF+'type'),URIRef(SH+'ValidationResult')):
        finding={}
        for label,predicate in (('focus_node','focusNode'),('path','resultPath'),('shape','sourceShape'),('severity','resultSeverity'),('message','resultMessage'),('constraint','sourceConstraintComponent')):
            value=report.value(result,URIRef(SH+predicate)); finding[label]=encode(value) if value is not None else None
        findings.append(finding)
    findings.sort(key=canonical_bytes)
    if len(findings)>bound['result_rows']:
        return {'status':'resource_limit','complete':False,'limit':'result_rows','findings':findings[:bound['result_rows']],'inference':'none','graph_scope':selected}
    return {'status':'conformant' if conforms else 'violation','complete':True,'conforms':bool(conforms),
        'findings':findings,'diagnostics':[],'inference':'none','graph_scope':selected,'authority':False}

"""Standard-library public API; optional packages only run inside the worker."""
from pathlib import Path
from ontology_core import (OntologyError, canonical_bytes, decode_json, load_project,
    read_bytes, require, safe_path, sha256)
from ontology_advanced import CONFIG, VERSION, load_advanced, load_extensions
from ontology_limits import limits as resolve_limits


def contract_asset(relative):
    package=Path(__file__).resolve().parents[1]
    candidates=[package.parents[1]/'ONTOLOGY-depo',package.parents[2]/'reference-assets/ONTOLOGY-depo']
    for directory in candidates:
        path=directory/relative
        if path.is_file(): return path
    raise OntologyError('missing_contract','The selected installed standards contract is absent: '+relative)


def _prepare(root,overrides=None):
    overrides=overrides or {}
    for path,data in overrides.items():
        safe_path(root,path,must_exist=False)
        require(isinstance(data,bytes),'invalid_override','Preview overrides must contain exact bytes.')
    cfg=load_advanced(root,required=True,_overrides=overrides)
    require(cfg['profiles'].get('standards',{}).get('enabled',False),'profile_disabled','Standards profile is disabled.')
    project=load_project(root,validate=False,_overrides={k:v for k,v in overrides.items() if k!=CONFIG and not k.startswith('ONTOLOGY/extensions/')})
    extensions,extra,sources=load_extensions(project,cfg,_overrides=overrides)
    allowed=set(project.config['project_files']+project.config['binding_files']+project.config.get('competency_files',[]))|{CONFIG}|set(extra)
    require(set(overrides)<=allowed,'canonical_scope','Preview includes unselected advanced files.')
    context=project.context(); context.pop('snapshot_sha256',None)
    context['advanced_version']=VERSION
    context['advanced_inputs']={CONFIG:sha256(overrides[CONFIG] if CONFIG in overrides else read_bytes(safe_path(root,CONFIG))),**extra}
    context['advanced_sources']=sources
    package=Path(__file__).resolve().parents[1]
    context['standards_profile_sha256']=sha256(package/'profiles/standards-v1.json')
    context['contracts']={relative:sha256(contract_asset(relative)) for relative in ('rules/finite-profile-v1.json','shapes/ontology-v1.ttl')}
    from ontology_reasoning import RULES
    rule_manifest=decode_json(read_bytes(contract_asset('rules/finite-profile-v1.json')))
    require(rule_manifest.get('schema_version')==1 and rule_manifest.get('version')=='1.0.0' and set(rule_manifest.get('rules',{}))==set(RULES),'unsupported_rule_profile','Selected finite rule manifest differs from the supported engine.')
    context['preview']=bool(overrides)
    context['snapshot_sha256']=sha256(canonical_bytes(context))
    shapes=[read_bytes(contract_asset('shapes/ontology-v1.ttl')).decode()]
    for ext in extensions:
        for ref in ext.get('shapes',[]): shapes.append((overrides[ref['path']] if ref['path'] in overrides else read_bytes(safe_path(root,ref['path']))).decode())
    payload={'records':project.records,'sources':project.sources+sources,'extensions':extensions,
             'context':context,'shapes':shapes,'inference_enabled':cfg['profiles'].get('inference',{}).get('enabled',False)}
    return cfg,payload,project


def health(root):
    from ontology_profiles import health as profile_health
    return profile_health(root,'standards')


def call(root,operation,*,overrides=None,limits=None,cancel=None,expected_snapshot=None,**options):
    from ontology_worker import run_worker
    from ontology_profiles import health as profile_health
    try:
        cfg,payload,project=_prepare(root,overrides)
        readiness=profile_health(root,'standards')
        require(readiness['status']=='ready','backend_unavailable','Standards profile is not ready: '+readiness['status'])
        if expected_snapshot is not None:
            require(payload['context']['snapshot_sha256']==expected_snapshot,'stale_input','Approved input snapshot changed; the old result cannot be reused.')
        if operation=='infer': require(cfg['profiles'].get('inference',{}).get('enabled',False),'profile_disabled','Inference profile is disabled.')
        bound=resolve_limits(cfg['limits'],limits)
        supplied_shapes=options.pop('shapes',None)
        payload.update(options)
        if supplied_shapes is not None:
            require(isinstance(supplied_shapes,(str,list)),'invalid_shapes','Shapes must be selected Turtle text or a list of texts.')
            payload['shapes'] += [supplied_shapes] if isinstance(supplied_shapes,str) else supplied_shapes
        if operation=='validate' and any(d['severity']=='error' for d in project.diagnostics) and payload.get('triples') is None:
            core_errors=[d for d in project.diagnostics if d['severity']=='error']
        else: core_errors=[]
        result=run_worker(Path(root)/'.venv-ontology-standards/bin/python',operation,payload,bound,cancel=cancel)
        result['context']=payload['context']
        if core_errors and result.get('complete'):
            result.update(status='violation',conforms=False); result.setdefault('diagnostics',[]).extend(core_errors)
        # Reopen exact inputs after execution; preview bytes remain frozen and are
        # never mistaken for canonical state. Queries do not refresh any store.
        now=_prepare(root,overrides)[1]['context']['snapshot_sha256']
        if now!=payload['context']['snapshot_sha256']:
            return {'status':'stale_input','complete':False,'trusted':False,'context':payload['context'],
                'diagnostics':[{'code':'stale_input','message':'Selected inputs changed during the worker operation.'}]}
        if len(canonical_bytes(result))>bound['output_bytes']:
            return {'status':'output_limit','complete':False,'context':payload['context'],
                'diagnostics':[{'code':'output_limit','message':'Complete result with provenance exceeds output_bytes.'}]}
        return result
    except OntologyError as exc:
        return {'status':exc.code,'complete':False,'diagnostics':[exc.as_dict()]}


def dataset(root,graphs=None,**kwargs): return call(root,'dataset',graphs=graphs or ['asserted','derived','inferred','external'],**kwargs)
def query(root,text,graphs=None,**kwargs): return call(root,'query',query=text,graphs=graphs or ['asserted'],**kwargs)
def validate(root,graphs=None,shapes=None,triples=None,**kwargs): return call(root,'validate',graphs=graphs or ['asserted','derived','external'],shapes=shapes,triples=triples,**kwargs)
def infer(root,goals=None,premise_ids=None,**kwargs): return call(root,'infer',goals=goals or [],premise_ids=premise_ids,**kwargs)
def export(root,format,selected_graph=None,**kwargs): return call(root,'export',format=format,selected_graph=selected_graph,**kwargs)
def stage_import(root,data,format,manifest=None,**kwargs): return call(root,'parse',data=data,format=format,manifest=manifest,**kwargs)


def freshness(root,result):
    try:
        context=_prepare(root)[1]['context']
        current=context['snapshot_sha256']==result.get('context',{}).get('snapshot_sha256')
        return {'status':'current' if current else 'stale_input','complete':current,'context':context}
    except OntologyError as exc: return {'status':exc.code,'complete':False,'diagnostics':[exc.as_dict()]}

"""Completion capture and explicit user preference changes; no background worker."""
from __future__ import annotations

from memory_core import load_config, json_bytes, sha256, validate_config
from memory_paths import require, safe_read_bytes

TRIGGERS = ("work-completed", "task-completed", "decision-recorded", "failure-observed")


def capture_status(root):
    config = load_config(root)
    enabled = config["integration"]["automatic_capture"]
    return {"automatic_capture": enabled, "triggers": list(TRIGGERS),
            "config_sha256": sha256(safe_read_bytes(root, "memory.yaml")),
            "read_only": True,
            "message": "Memory automatic capture is " + ("on." if enabled else "off.")}


def set_capture(root, enabled, expected_config_sha256):
    """Called only for an explicit user setting change; preserve every other field."""
    from memory_recovery import project_lock, atomic_replace, pending_transactions
    require(type(enabled) is bool, "invalid_setting", "Automatic capture must be a boolean.")
    raw = safe_read_bytes(root, "memory.yaml")
    require(sha256(raw) == expected_config_sha256, "config_conflict", "Memory configuration changed; inspect it again.")
    config = load_config(root)
    if config["integration"]["automatic_capture"] == enabled:
        return {**capture_status(root), "read_only": False, "mutated": False}
    with project_lock(root):
        require(not pending_transactions(root), "recovery_pending", "Resolve pending memory publication before changing configuration.")
        from memory_maintenance import pending_reindexes
        require(not pending_reindexes(root, config), "recovery_pending", "Resolve pending index maintenance before changing configuration.")
        config["integration"]["automatic_capture"] = enabled
        validate_config(config)
        atomic_replace(root, "memory.yaml", json_bytes(config), expected_config_sha256)
    return {**capture_status(root), "read_only": False, "mutated": True,
            "index_refresh_required": config["backend"]["enabled"],
            "current_readiness": __import__("memory_maintenance").maintenance_followup(root)}


def capture(root, payload, grant_file, actor, *, trigger):
    """Publish a reviewed checkpoint finding when enabled, using existing authority.

    The Director supplies evidence and judgment. This helper does not invent
    findings, authorize itself, or turn a Task transition into a memory write.
    Existing transaction IDs make a repeated completion call idempotent.
    """
    require(trigger in TRIGGERS, "invalid_trigger", "Unsupported automatic capture checkpoint.")
    if not load_config(root)["integration"]["automatic_capture"]:
        return {"status": "skipped", "reason": "automatic_capture_off", "mutated": False, "trigger": trigger}
    require(payload.get("operation") in {"publish", "supersede"}, "invalid_capture", "Capture publishes a finding or its reviewed successor.")
    from memory_publish import publish
    result = publish(root, payload, grant_file, actor)
    return {"status": "captured", "trigger": trigger, "publication": result}


# Optional action guard adapter.  Standalone/core use imports no ontology runtime.
def _ontology_checkpoint(*, targets=True):
    import sys as _sys
    _module = _sys.modules.get("ontology_guards")
    if _module is not None:
        _module.checkpoint(targets=targets)


def _ontology_guard_adapter(function, family, root_argument, target_paths):
    import functools as _functools
    import inspect as _inspect
    @_functools.wraps(function)
    def guarded(*args, **kwargs):
        import importlib.util as _util
        import sys as _sys
        from pathlib import Path as _Path
        arguments = dict(_inspect.signature(function).bind(*args, **kwargs).arguments)
        if root_argument == "@depot":
            selected_root = installed_locations()[0]
        else:
            selected_root = arguments[root_argument]
            if not isinstance(selected_root, (_Path, str)):
                selected_root = getattr(selected_root, "project_root", getattr(selected_root, "root", selected_root))
        selected_root = _Path(selected_root).absolute()
        config_path = selected_root / "ontology-advanced.yaml"
        if not config_path.exists() and not config_path.is_symlink():
            return function(*args, **kwargs)
        if family == "template" and arguments.get("command") == "check":
            return function(*args, **kwargs)
        import json as _json
        import hashlib as _hashlib
        def unique_pairs(pairs):
            value = {}
            for key, item in pairs:
                if key in value:
                    raise ValueError("duplicate guard configuration key")
                value[key] = item
            return value
        try:
            if config_path.is_symlink():
                raise ValueError("symbolic guard configuration")
            config = _json.loads(config_path.read_text(), object_pairs_hook=unique_pairs)
            selected = config.get("profiles", {}).get("guards", {"enabled": False})
            if config.get("schema_version") != 1 or not isinstance(selected, dict) or type(selected.get("enabled")) is not bool:
                raise ValueError("unsupported guard configuration")
        except (OSError, ValueError, AttributeError) as exc:
            raise _ontology_adapter_error("guard_schema", "Guard configuration is unreadable or unsupported.", {}) from exc
        if not selected["enabled"]:
            if set(selected) != {"enabled"}:
                raise _ontology_adapter_error("guard_schema", "Disabled guard configuration has unsupported fields.", {})
            return function(*args, **kwargs)
        script = selected_root / ".agents/skills/ontology/scripts/ontology_guards.py"
        if not script.is_file() or any(parent.is_symlink() for parent in (script, *script.parents)):
            raise _ontology_adapter_error("guard_unavailable", "Enabled guards require their current project-local installed adapter.", {})
        current_sha256 = _hashlib.sha256(script.read_bytes()).hexdigest()
        module = _sys.modules.get("ontology_guards")
        if module is not None and (_Path(module.__file__).resolve() != script.resolve()
                or getattr(module, "ENGINE_SOURCE_SHA256", None) != current_sha256):
            raise _ontology_adapter_error("guard_stale", "Loaded guard code differs from this selected project's current installed bytes; use a fresh owning-helper process after reviewed repair.", {})
        if module is None:
            spec = _util.spec_from_file_location("ontology_guards", script)
            module = _util.module_from_spec(spec)
            _sys.modules["ontology_guards"] = module
            _sys.path.insert(0, str(script.parent))
            spec.loader.exec_module(module)
        targets = list(target_paths)
        if family == "setup":
            destination = _Path(arguments["destination"]).absolute()
            try:
                relative = destination.relative_to(selected_root).as_posix()
            except ValueError:
                raise _ontology_adapter_error("guard_scope", "Setup target escapes the selected depot.", {})
            targets.extend([relative + "/control_records/project-setup.json", relative + "/AGENTS.md", relative + "/ROLE.md"])
        try:
            return module.dispatch(lambda: function(*args, **kwargs), family, function.__name__, selected_root, arguments, targets)
        except module.GuardError as exc:
            raise _ontology_adapter_error(exc.code, str(exc), exc.details) from exc
    return guarded


def _ontology_adapter_error(code, message, details):
    return __import__("memory_paths").MemoryError(code, message, details)

ONTOLOGY_GUARDED_ACTIONS = ['set_capture', 'capture']
set_capture = _ontology_guard_adapter(set_capture, 'memory', 'root', ['memory.yaml'])
capture = _ontology_guard_adapter(capture, 'memory', 'root', ['memory.yaml'])

"""Deterministic project retrieval with optional guarded semantic ranking."""
import re
from pathlib import Path

from memory_core import MemoryError, load_config, load_records
from memory_paths import iter_corpus, safe_read_bytes
from memory_normalization import normalize_document, cache_diagnostic, digest


def collect_documents(root, config=None, historical=False):
    """Return current permitted bytes; this function never builds an index."""
    from memory_core import reject_sensitive
    config = config or load_config(root)
    documents, limitations = [], []
    for record in load_records(root, config=config, historical=historical):
        meta = record["metadata"]
        doc = {"kind": "memory", "path": record["path"], "sha256": record["sha256"],
               "source_identity": meta["id"], "metadata": meta,
               "segments": [{"text": meta["title"] + "\n" + record["body"],
                             "heading": meta["title"], "locator": record["path"]}],
               "limitations": meta["limitations"], "diagnostics": record["diagnostics"], "evidence": record["evidence"]}
        reject_sensitive(record["body"])
        documents.append(doc)
    for source in iter_corpus(root, config):
        rel = Path(source).relative_to(Path(root)).as_posix() if Path(source).is_absolute() else str(source)
        try:
            doc = normalize_document(root, rel, config)
            # Screen the complete source representation before exposing excerpts.
            reject_sensitive("\n".join(s["text"] for s in doc["segments"]))
            stale = cache_diagnostic(root, config, rel, doc["sha256"], doc.get("extractor"))
            if stale:
                doc["limitations"].append(stale)
            documents.append(doc)
            limitations.extend(f"{rel}: {item}" for item in doc["limitations"])
        except MemoryError as error:
            limitations.append(f"Source excluded or unavailable ({error.code}).")
    return documents, sorted(set(limitations))


def lexical_score(text, query):
    text, query = text.casefold(), query.casefold()
    terms = sorted(set(re.findall(r"[\w]+(?:[./:_-][\w]+)*", query)))
    if not terms:
        return 0
    phrase = text.count(query)
    hits = sum(min(text.count(term), 20) for term in terms)
    coverage = sum(term in text for term in terms)
    return phrase * 100 + coverage * 10 + hits


def _excerpt(text, query, length=700):
    needle = query.casefold()
    pos = text.casefold().find(needle)
    if pos < 0:
        terms = re.findall(r"\w+", needle)
        found = [text.casefold().find(t) for t in terms if t in text.casefold()]
        pos = min(found) if found else 0
    start = max(0, pos - 100)
    return ("…" if start else "") + text[start:start + length] + ("…" if len(text) > start + length else "")


def rank_documents(documents, query, limit, ranking=None):
    """One result per known evidence identity, retaining all representation paths."""
    ranked = []
    use_backend = ranking is not None
    ranking = {} if ranking is None else ranking
    for doc in documents:
        segments = doc["segments"]
        if not segments:
            continue
        best = max(segments, key=lambda s: lexical_score(s["text"], query))
        score = lexical_score(best["text"] + "\n" + doc["path"], query)
        semantic = ranking.get((doc["path"], doc["sha256"]))
        if semantic is not None:
            score = semantic
        elif use_backend:
            continue
        if score <= 0 and semantic is None:
            continue
        result = {"kind": doc["kind"], "path": doc["path"], "sha256": doc["sha256"],
                  "source_identity": doc["source_identity"], "locator": best["locator"],
                  "heading": best["heading"], "excerpt": _excerpt(best["text"], query),
                  "score": score, "limitations": list(doc["limitations"]),
                  "diagnostics": doc.get("diagnostics", []),
                  "authority": "Source data; inspect current governing sources before acting."}
        for field in ("labels", "references", "bibliography_keys", "environments", "page", "line"):
            if field in best:
                result[field] = best[field]
        if doc["kind"] == "memory":
            result.update({"record_id": doc["metadata"]["id"], "state": doc["metadata"]["state"],
                           "sources": doc["metadata"]["sources"], "claim": doc["metadata"]["claim"],
                           "confidence": doc["metadata"]["confidence"], "evidence": doc.get("evidence"),
                           "verified_current": doc.get("evidence", {}).get("verified_current", False)})
        ranked.append(result)
    ranked.sort(key=lambda r: (-r["score"], r["source_identity"], r["path"], r["locator"]))
    unique = {}
    for result in ranked:
        identity = result["source_identity"]
        if identity not in unique:
            result["representations"] = []
            unique[identity] = result
        unique[identity]["representations"].append({"path": result["path"], "sha256": result["sha256"], "locator": result["locator"]})
    return list(unique.values())[:limit]


def search(root, query, config=None, historical=False, packet=None, limit=None, mode="auto"):
    if not isinstance(query, str) or not query.strip() or len(query) > 4096:
        raise MemoryError("invalid_query", "Supply a nonempty query of at most 4096 characters.")
    if mode not in {"auto", "lexical", "hybrid"}:
        raise MemoryError("invalid_mode", "Supported modes are auto, lexical and hybrid.")
    if packet is not None:
        from memory_packet import search_packet
        return search_packet(root, packet, query, limit=limit)
    config = config or load_config(root, optional=True)
    if config is None:
        return {"status": "unconfigured", "mode": "lexical", "mutated": False,
                "results": [], "limitations": ["No project memory configuration; inspect permitted source files directly."]}
    if mode == "auto":
        mode = config["retrieval"]["mode"]
    limit = config["retrieval"]["max_results"] if limit is None else limit
    if not isinstance(limit, int) or isinstance(limit, bool) or not 1 <= limit <= 200:
        raise MemoryError("invalid_limit", "Result limit must be between 1 and 200.")
    docs, limitations = collect_documents(root, config, historical=historical)
    ranking = None
    actual_mode = "lexical"
    if mode != "lexical" and not historical:
        if config["backend"]["enabled"] and config["backend"]["semantic_enabled"]:
            from basic_memory_adapter import query as backend_query
            response = backend_query(root, query, config, mode="hybrid", limit=limit, packet=None)
            limitations.extend(response.get("limitations", []))
            if response.get("available"):
                # Recheck every locator/digest against current allowed canonical bytes.
                current = {(d["path"], d["sha256"]): d for d in docs}
                ranking = {(r["path"], r["sha256"]): r["score"] for r in response.get("results", [])
                           if (r.get("path"), r.get("sha256")) in current}
                actual_mode = response["mode"]
            else:
                limitations.append("Semantic backend unavailable or uncertified; using lexical retrieval without maintenance.")
        else:
            limitations.append("Semantic backend disabled; results use deterministic lexical retrieval.")
    # Fail if a source changed while ranking, rather than returning a stale version as current.
    current_docs = []
    for doc in docs:
        if digest(safe_read_bytes(root, doc["path"])) == doc["sha256"]:
            current_docs.append(doc)
        else:
            limitations.append("A source changed during retrieval and was excluded; inspect it again.")
    docs = current_docs
    results = rank_documents(docs, query, limit, ranking=ranking)
    return {"status": "ok" if results else "no_match" if docs else "empty", "mode": actual_mode,
            "mutated": False, "project_id": config["project"]["id"], "results": results,
            "limitations": sorted(set(limitations)), "historical": historical}

